L["Use TomTom's arrow"] = "TomToms Pfeil benutzen"
L["Hides Polestar's arrow in favour of TomTom's, except on the way to another continent, where TomTom's arrow cannot point."] = "Blendet Polestars Pfeil zugunsten von TomToms aus, außer auf dem Weg zu einem anderen Kontinent, wohin TomToms Pfeil nicht zeigen kann."
L["Automation"] = "Automatisierung"
L["Accept guide quests"] = "Guide-Quests annehmen"
L["Only quests in the next steps of your open guides. Hold Shift to skip."] = "Nur Quests aus den nächsten Schritten deiner offenen Guides. Halte Umschalt gedrückt, um es auszulassen."
L["Turn in guide quests"] = "Guide-Quests abgeben"
L["Never picks between rewards. Hold Shift to skip."] = "Wählt nie zwischen Belohnungen. Halte Umschalt gedrückt, um es auszulassen."
L["Skip grey quests"] = "Graue Quests überspringen"
L["Pick a guide for me"] = "Guide für mich wählen"
L["Where to level next"] = "Wo du als Nächstes levelst"
L["Where a guide offers more than one zone to continue in (/polestar path)."] = "Wenn ein Guide mehr als ein Gebiet zum Weitermachen anbietet (/polestar path)."
