L["Take the recommended zone"] = "Empfohlenes Gebiet nehmen"
L["Trainer reminders"] = "Lehrer-Erinnerungen"
L["A note in the guide window, with the nearest trainer of your class, when new skills are waiting."] = "Ein Hinweis im Guide-Fenster mit dem nächsten Lehrer deiner Klasse, wenn neue Fähigkeiten warten."
