L["The accent follows your class: warlock purple, shaman blue, druid orange. Picking your own accent turns this off."] = "Der Akzent folgt deiner Klasse: Hexenmeister lila, Schamane blau, Druide orange. Wählst du einen eigenen Akzent, schaltet sich das aus."
