L["Background colour"] = "Hintergrundfarbe"
L["The ground of every Polestar window. Right-click to go back to the scheme's. Text always stays legible: a colour too light for it is darkened."] = "Der Untergrund jedes Polestar-Fensters. Rechtsklick, um zu der des Farbschemas zurückzukehren. Text bleibt immer lesbar: Eine dafür zu helle Farbe wird abgedunkelt."
L["Brightness"] = "Helligkeit"
