L["In screen pixels; a thicker border grows outward. Right-click to reset."] = "In Bildschirmpixeln; ein dickerer Rand wächst nach außen. Rechtsklick zum Zurücksetzen."
L["Starlit band"] = "Sternenband"
L["The night sky with its stars across the top of every window. Off: the plain background."] = "Der Nachthimmel mit seinen Sternen am oberen Rand jedes Fensters. Aus: der einfache Hintergrund."
