L["Start recording"] = "Aufzeichnung starten"
L["Write quests, routes and world data for guide authors. Off until you start it."] = "Schreibt Quests, Routen und Weltdaten für Guide-Autoren. Aus, bis du es startest."
L["Print status"] = "Status ausgeben"
L["The Polestar Recorder addon is not loaded. Enable it in the AddOns list on the character screen to record your play for guide authoring."] = "Das Addon Polestar Recorder ist nicht geladen. Aktiviere es in der AddOn-Liste der Charakterauswahl, um dein Spiel für die Guide-Erstellung aufzuzeichnen."
L["Recording"] = "Aufzeichnung"
L["Stop recording"] = "Aufzeichnung beenden"
L["Nothing more is written until you start it again."] = "Es wird nichts mehr geschrieben, bis du sie wieder startest."
L["A community project"] = "Ein Community-Projekt"
L["Leveling guides for World of Warcraft: Forever."] = "Leveling-Guides für World of Warcraft: Forever."
L["Version"] = "Version"
L["Why Polestar"] = "Warum Polestar"
L["Leveling guides have become a business: the best routes sit behind subscriptions and paywalls. Polestar goes the other way. It is free, open source under the GPL-3.0, and built by the community that plays it."] = "Leveling-Guides sind zum Geschäft geworden: Die besten Routen liegen hinter Abos und Bezahlschranken. Polestar geht den anderen Weg. Es ist kostenlos, Open Source unter der GPL-3.0 und von der Community gebaut, die es spielt."
L["Polestar doesn't claim to be the fastest guide, or the smoothest. It is a free alternative, and it gets better with time."] = "Polestar behauptet nicht, der schnellste oder reibungsloseste Guide zu sein. Es ist eine kostenlose Alternative, und es wird mit der Zeit besser."
L["Anyone can read the code, fix a step, sharpen a route or write a new guide, and contributions are welcome. The GPL keeps it that way: every copy and every fork stays open."] = "Jeder kann den Code lesen, einen Schritt korrigieren, eine Route verbessern oder einen neuen Guide schreiben, und Beiträge sind willkommen. Die GPL sorgt dafür, dass das so bleibt: Jede Kopie und jeder Fork bleibt offen."
L["It is young and still in beta, so expect the odd wrong step, waypoint or quest. Every report and every fix tunes it, and together we'll get it where it should be."] = "Es ist jung und noch in der Beta, rechne also mit dem einen oder anderen falschen Schritt, Wegpunkt oder einer falschen Quest. Jede Meldung und jede Korrektur verbessert es, und gemeinsam bringen wir es dorthin, wo es sein soll."
L["Open source and free is the future."] = "Open Source und kostenlos ist die Zukunft."
L["show or hide the guide window"] = "Guide-Fenster ein- oder ausblenden"
L["choose a guide"] = "einen Guide wählen"
L["move through steps"] = "durch die Schritte gehen"
L["report a problem with a step on the Polestar Discord"] = "ein Problem mit einem Schritt im Polestar-Discord melden"
L["every command"] = "alle Befehle"
L["Credits"] = "Danksagung"
L["Inter typeface by The Inter Project Authors, SIL Open Font License 1.1."] = "Schrift Inter von The Inter Project Authors, SIL Open Font License 1.1."
L["Wordmark set in Cinzel by The Cinzel Project Authors, SIL Open Font License 1.1."] = "Wortmarke gesetzt in Cinzel von The Cinzel Project Authors, SIL Open Font License 1.1."
L["Quest and map data includes pfQuest by shagu (MIT License)."] = "Quest- und Kartendaten enthalten pfQuest von shagu (MIT-Lizenz)."
L["Discord and its logo are trademarks of Discord Inc.; the logo marks the link to the Polestar Discord."] = "Discord und sein Logo sind Marken von Discord Inc.; das Logo kennzeichnet den Link zum Polestar-Discord."
L["With EllesmereUI installed, Polestar can follow its accent, font and panel colour through its public skinning API."] = "Ist EllesmereUI installiert, kann Polestar über dessen öffentliche Skinning-API seinem Akzent, seiner Schrift und seiner Fensterfarbe folgen."
L["Maintenance"] = "Wartung"
L["Reset all settings"] = "Alle Einstellungen zurücksetzen"
L["Every Polestar setting back to default. Progress is kept."] = "Jede Polestar-Einstellung zurück auf den Standard. Der Fortschritt bleibt erhalten."
L["Reset positions"] = "Positionen zurücksetzen"
L["Guide window, arrow and these windows."] = "Guide-Fenster, Pfeil und diese Fenster."
L["Guides made by other players: switch them on or off, and choose where suggestions come from."] = "Guides von anderen Spielern: ein- oder ausschalten und wählen, woher die Vorschläge kommen."
L["The data recorder for guide authors."] = "Der Datenrekorder für Guide-Autoren."
L["Why Polestar exists, its commands and its credits."] = "Warum es Polestar gibt, seine Befehle und seine Danksagung."
L["Nothing to set here yet: the module behind this page is not loaded."] = "Hier gibt es noch nichts einzustellen: Das Modul hinter dieser Seite ist nicht geladen."
L["No settings match \226\128\156%s\226\128\157."] = "Keine Einstellungen passen zu „%s“."
L["1 setting matches"] = "1 Einstellung passt"
L["%d settings match"] = "%d Einstellungen passen"
L["Reset page"] = "Seite zurücksetzen"
L["Reload UI"] = "UI neu laden"
L["Search settings"] = "Einstellungen durchsuchen"
L["Open Polestar settings"] = "Polestar-Einstellungen öffnen"
L["Close the game menu to see Polestar's settings (it cannot be closed for you in combat)."] = "Schließe das Spielmenü, um Polestars Einstellungen zu sehen (im Kampf kann es nicht für dich geschlossen werden)."
L["Expand step tips"] = "Schritt-Tipps ausklappen"
L["Start each step with its tip in full instead of one line."] = "Jeden Schritt mit seinem vollständigen Tipp statt einer Zeile beginnen."
L["Walk real paths"] = "Echten Wegen folgen"
L["The arrow follows paths on the ground around cliffs, water and walls, on Polestar's walking maps, with Shortest Path Forever's router by Cillian Berragan. Off: it points straight at each stop."] = "Der Pfeil folgt Wegen am Boden um Klippen, Wasser und Mauern, auf Polestars Wegekarten, mit dem Router von Shortest Path Forever von Cillian Berragan. Aus: Er zeigt direkt auf jede Station."
L["Route lines"] = "Routenlinien"
L["Class teleports"] = "Klassen-Teleports"
L["Routes may start with a Teleport spell you know (a mage's city teleports, a druid's Moonglade) when it is faster. A city teleport needs a Rune of Teleportation in your bags."] = "Routen können mit einem Teleportzauber beginnen, den du kennst (die Stadtteleports eines Magiers, die Mondlichtung eines Druiden), wenn das schneller ist. Ein Stadtteleport braucht eine Rune der Teleportation in deinen Taschen."
L["Share boat times"] = "Bootszeiten teilen"
L["Riding a boat, zeppelin, tram or lift times it; your guild and group get those times and you get theirs, so the arrow can say when the next one leaves."] = "Eine Fahrt mit Boot, Zeppelin, Bahn oder Aufzug wird gemessen; deine Gilde und Gruppe erhalten diese Zeiten und du ihre, damit der Pfeil sagen kann, wann der nächste abfährt."
L["Warn about missable quests"] = "Vor verpassbaren Quests warnen"
L["Before you take a quest that closes another for good, says which in chat and leaves the accept to you."] = "Bevor du eine Quest nimmst, die eine andere endgültig schließt, sagt es im Chat welche und überlässt dir das Annehmen."
L["The arrow's target, the stops of its travel route, the step's other goals, the areas their mobs and objects spawn in, and the route lines."] = "Das Ziel des Pfeils, die Stationen seiner Reiseroute, die anderen Ziele des Schritts, die Gebiete, in denen ihre Mobs und Objekte spawnen, und die Routenlinien."
L["The arrow's target, the areas it spawns in, and the route line."] = "Das Ziel des Pfeils, die Gebiete, in denen es spawnt, und die Routenlinie."
L["Moving dots from you to the target on the world map and the minimap, along the travel route, while route lines are off."] = "Wandernde Punkte von dir zum Ziel auf der Weltkarte und der Minikarte, entlang der Reiseroute, solange Routenlinien aus sind."
L["Talents"] = "Talente"
L["Talent plan"] = "Talentplan"
L["This translation was made with AI. Help improve it on Discord."] = "Diese Übersetzung wurde mit KI erstellt. Hilf auf Discord, sie zu verbessern."
L["Close the game menu to see Polestar's settings."] = "Schließe das Spielmenü, um Polestars Einstellungen zu sehen."
L["Integrations"] = "Integrationen"
L["Settings for other addons Polestar works with, shown when they are installed."] = "Einstellungen für andere Addons, mit denen Polestar zusammenarbeitet, sichtbar, wenn sie installiert sind."
L["None of the addons Polestar works with is installed."] = "Keines der Addons, mit denen Polestar zusammenarbeitet, ist installiert."
L["The skin's font (the default: the game's own, Fira Sans in Halo), or a font of your choice."] = "Die Schrift des Designs (Standard: die des Spiels, Fira Sans in Halo) oder eine Schrift deiner Wahl."
L["The skin's font"] = "Die Schrift des Designs"
L["Skin"] = "Design"
L["The skin's arrow"] = "Der Pfeil des Designs"
L["Lock arrow and buttons"] = "Pfeil und Knöpfe sperren"
L["Stops stray drags on the arrow, the action buttons and the flight and instance timers. Shift-drag still moves them."] = "Verhindert versehentliches Ziehen des Pfeils, der Aktionsknöpfe und der Flug- und Instanz-Timer. Mit Umschalt lassen sie sich weiterhin verschieben."
L["Line style"] = "Linienstil"
L["Bar at the bottom"] = "Leiste unten"
L["With Grow upward, put the tabs and the step bar at the bottom edge, next to where the window is pinned."] = "Setzt bei „Nach oben wachsen“ die Reiter und die Schrittleiste an den unteren Rand, neben die Stelle, an der das Fenster verankert ist."
L["Close offers the guide skips"] = "Angebote schließen, die der Guide überspringt"
L["After Polestar accepts or turns in a quest, closes the quest window the NPC opens next when the guide skips its quests. Hold Shift to keep it open."] = "Wenn Polestar eine Quest annimmt oder abgibt, schließt er das Questfenster, das der NPC danach öffnet, wenn der Guide deren Quests überspringt. Shift gedrückt halten, um es offen zu lassen."
L["Elite and escort quests the guides mark for a group. Ask at each, or answer them all: with a group (a party levelling together) or skip them (solo). Discovery, Group quests changes one."] = "Elite- und Eskortquests, die die Guides für eine Gruppe markieren. Frag bei jeder nach, oder beantworte alle auf einmal: mit einer Gruppe (eine Gruppe, die gemeinsam levelt) oder überspringen (solo). Entdecken, Gruppenquests ändert eine davon."
L["Ask me at each"] = "Bei jeder fragen"
L["Do them with a group"] = "Mit einer Gruppe machen"
L["Skip them"] = "Überspringen"
L["Offer class quests"] = "Klassenquests anbieten"
L["When one of your class's Class guides opens (your level, its first quest), the guide window offers to open it in a tab."] = "Wenn sich einer der Klassen-Guides deiner Klasse öffnet (deine Stufe, seine erste Quest), bietet das Guide-Fenster an, ihn in einem Tab zu öffnen."
L["Celebrating the supporters, contributors and bug reporters behind Polestar."] = "Wir feiern die Unterstützer, Mitwirkenden und Fehlermelder hinter Polestar."
L["Position trails, marks and the list of spots to walk, in a small window."] = "Positionsspuren, Markierungen und die Liste der abzulaufenden Orte in einem kleinen Fenster."
L["Reset guide progress?"] = "Fortschritt zurücksetzen?"
L["Reset progress"] = "Fortschritt zurücksetzen"
L["Reset all settings?"] = "Alle Einstellungen zurücksetzen?"
L["Reset all"] = "Alles zurücksetzen"
L["Live"] = "Live"
L["Rot Hide Mongrel"] = "Bastard der Moderfelle"
L["Waiting to upload"] = "Wartet auf Upload"
L["Chunks the Polestar Uploader has not sent yet."] = "Datenpakete, die der Polestar Uploader noch nicht gesendet hat."
L["Stored"] = "Gespeichert"
L["Last uploaded chunk"] = "Zuletzt hochgeladenes Datenpaket"
L["Recordings"] = "Aufzeichnungen"
L["Chunks waiting, the last upload and the install id, in chat."] = "Wartende Datenpakete, der letzte Upload und die Installations-ID im Chat."
L["Characters"] = "Charaktere"
L["Icon pack"] = "Symbolpaket"
L["The medallion under every mark on the world map and the minimap. The skin's: Polestar's, Halo's, or Hearth's for Hearth and the game's own looks. Glyphs only: no medallion."] = "Das Medaillon unter jeder Markierung auf der Weltkarte und der Minikarte. Das des Designs: das von Polestar, von Halo oder, bei Hearth und dem Aussehen des Spiels, das von Hearth. Nur Glyphen: kein Medaillon."
L["The skin's icons"] = "Die Symbole des Designs"
L["Glyphs only"] = "Nur Glyphen"
L["Use deathskips"] = "Deathskips benutzen"
L["Where dying on purpose and taking the Spirit Healer's resurrection gets you there sooner, the guide shows a step for it. It costs durability and, from level 11, resurrection sickness. Always off on Hardcore characters."] = "Wo es dich schneller ans Ziel bringt, absichtlich zu sterben und dich vom Geistheiler wiederbeleben zu lassen, zeigt der Guide einen Schritt dafür. Das kostet Haltbarkeit und ab Stufe 11 Auferstehungsschwäche. Bei Hardcore-Charakteren immer aus."
L["Text size"] = "Textgröße"
L["The size of Polestar's text, apart from the window scale. Changes at once. Right-click to reset."] = "Die Größe von Polestars Text, unabhängig von der Fenstergröße. Wirkt sofort. Rechtsklick zum Zurücksetzen."
L["Numbered pins for the steps ahead"] = "Nummerierte Markierungen für die nächsten Schritte"
L["A small pin with its step number where each of the next steps takes you, fainter the further ahead. As many as Up next shows, else five."] = "Eine kleine Markierung mit der Schrittnummer dort, wohin dich jeder der nächsten Schritte führt, umso blasser, je weiter voraus. So viele, wie „Als Nächstes“ zeigt, sonst fünf."
L["Run"] = "Ausführen"
L["Reset this page?"] = "Diese Seite zurücksetzen?"
L["Every setting on %s goes back to its default."] = "Jede Einstellung unter %s kehrt zu ihrem Standard zurück."
L["When a leveling guide ends"] = "Wenn ein Leveling-Guide endet"
L["Ask me: a window says the guide is done and offers the next one. Continue automatically: the next guide loads in the same tab."] = "Frag mich: Ein Fenster sagt, dass der Guide fertig ist, und bietet den nächsten an. Automatisch weitermachen: Der nächste Guide lädt im selben Tab."
L["Ask me"] = "Frag mich"
L["Continue automatically"] = "Automatisch weitermachen"
L["%d KiB"] = "%d KiB"
L["%.1f MB"] = "%.1f MB"
L["%d KB"] = "%d KB"
L["Show the whole step"] = "Ganzen Schritt zeigen"
L["Every goal of the step at once, finished ones kept, instead of one person at a time with the others on one line each."] = "Alle Ziele des Schritts auf einmal, erledigte bleiben stehen, statt einer Person nach der anderen mit den übrigen in je einer Zeile."
L["Maximum height"] = "Maximale Höhe"
L["How tall the window may grow, as a share of the screen. A longer step scrolls."] = "Wie hoch das Fenster werden darf, als Anteil am Bildschirm. Ein längerer Schritt wird gescrollt."
L["Hide the arrow with the guide"] = "Pfeil mit dem Guide ausblenden"
L["When the guide window is hidden, hide the arrow too."] = "Wenn das Guide-Fenster ausgeblendet ist, auch den Pfeil ausblenden."
L["Small conveniences: questing, travel, invitations, merchants, bags, trackers and the map."] = "Kleine Annehmlichkeiten: Questen, Reisen, Einladungen, Händler, Taschen, Tracker und die Karte."
L["Did you mean:"] = "Meintest du:"
L["In dungeons and battlegrounds"] = "In Dungeons und Schlachtfeldern"
L["How close"] = "Wie nah"
L["Include nearby hand-ins"] = "Abgaben in der Nähe einbeziehen"
L["Wait for Spoken"] = "Auf Spoken warten"
L["Waits 200 ms before each automatic quest accept, turn-in and reward pick, so Spoken has time to notice the window and read it."] = "Wartet 200 ms vor jedem automatischen Annehmen und Abgeben einer Quest und der Wahl der Belohnung, damit Spoken das Fenster bemerken und vorlesen kann."
L["Dynamic Questing"] = "Dynamisches Questen"
L["Sound for a new suggestion"] = "Ton für einen neuen Vorschlag"
L["Suggests objectives from later steps when you are near them, from your quest log and what is around you. They show under the step in a \"While you're here\" panel: click one to point the arrow there; right-click to dismiss it around here (dismissed twice, it stays away for the zone)."] = "Schlägt Ziele aus späteren Schritten vor, wenn du in ihrer Nähe bist, anhand deines Questlogs und deiner Umgebung. Sie erscheinen unter dem Schritt in einem Fenster „Wenn du schon hier bist“: Klicke auf einen, um den Pfeil dorthin zu richten; ein Rechtsklick blendet ihn hier in der Gegend aus (zweimal ausgeblendet, bleibt er für das Gebiet weg)."
L["A soft chime for each new suggestion (once when several come together), at the game's sound effects volume."] = "Ein leiser Signalton für jeden neuen Vorschlag (einmal, wenn mehrere zusammenkommen), in der Lautstärke der Soundeffekte des Spiels."
L["What's new"] = "Neuigkeiten"
L["When you abandon a guide quest"] = "Wenn du eine Guide-Quest abbrichst"
L["Always go back for it"] = "Immer dafür zurückgehen"
L["Always skip it"] = "Immer überspringen"
L["Ask me: the guide stays on its step, leads you back to the quest giver, and the guide window asks. Or always go back for the quest, or always skip it and the quests that follow from it; chat says which."] = "Fragen: Der Guide bleibt bei seinem Schritt, führt dich zurück zum Questgeber, und das Guide-Fenster fragt nach. Oder immer für die Quest zurückgehen, oder sie und die Quests, die darauf aufbauen, immer überspringen; der Chat sagt dir jeweils, was gilt."
L["Also a quest ready to hand in whose NPC is a little out of your way, when the guide hands it in later."] = "Auch eine abgabebereite Quest, deren NPC ein Stück abseits deines Wegs liegt, wenn der Guide sie erst später abgibt."
L["Hand-ins: how far out of your way"] = "Abgaben: wie weit abseits deines Wegs"
L["The seconds of extra walking a hand-in may cost, to its NPC and back on your way. One in the town you are in always shows; 0 keeps to those."] = "Die Sekunden zusätzlicher Laufzeit, die eine Abgabe kosten darf, zu ihrem NPC und zurück auf deinen Weg. Eine in der Stadt, in der du bist, wird immer angezeigt; 0 bleibt bei diesen."
L["Route line on the minimap"] = "Routenlinie auf der Minikarte"
L["The way to the goal on the minimap. Off keeps the guide pin there and the line on the world map. Its colour, opacity and size: the gear beside Guide > Arrow & routes > Route lines."] = "Der Weg zum Ziel auf der Minikarte. Aus lässt dort die Guide-Markierung und die Linie auf der Weltkarte. Farbe, Deckkraft und Größe: das Zahnrad neben Guide > Pfeil & Routen > Routenlinien."
L["Show and hide"] = "Anzeigen und ausblenden"
L["Floating button"] = "Schwebender Button"
L["Step key targets their mobs"] = "Schrittetaste visiert ihre Mobs an"
L["The step key also targets the mobs of the suggestions, nearest first, after the current step's own. It changes only out of combat."] = "Die Schrittetaste visiert nach denen des aktuellen Schritts auch die Mobs der Vorschläge an, die nächsten zuerst. Das ändert sich nur außerhalb des Kampfes."
L["Mark quests new in Forever"] = "In Forever neue Quests markieren"
L["A small infinity mark beside the name of a quest Forever added, in the guide, While you're here, the Codex and quest tooltips."] = "Ein kleines Unendlichkeitszeichen neben dem Namen einer Quest, die Forever hinzugefügt hat, im Guide, bei „Wenn du schon hier bist“, im Codex und in Quest-Tooltips."
L["The way to the goal on the world map and the minimap: a line or dots where you walk, lines where you fly, sail or ride, the legs after this one fainter. Drawn as Shortest Path Forever by Cillian Berragan draws them."] = "Der Weg zum Ziel auf der Weltkarte und der Minikarte: eine Linie oder Punkte, wo du läufst, Linien, wo du fliegst, segelst oder reitest, die Etappen nach dieser blasser. Gezeichnet, wie Shortest Path Forever von Cillian Berragan sie zeichnet."
L["How the route lines are drawn: one solid line, Polestar's dots, or sparkles that drift along the way to the goal (dots while Reduce motion is on)."] = "Wie die Routenlinien gezeichnet werden: als durchgehende Linie, als Punkte von Polestar oder als Funken, die auf dem Weg zum Ziel treiben (Punkte, solange Bewegung reduzieren an ist)."
L["A Polestar button in the game menu (Esc) that opens the guide menu."] = "Ein Polestar-Button im Spielmenü (Esc), der das Guide-Menü öffnet."
L["Backing"] = "Unterlegung"
L["Soft"] = "Weich"
L["Dark"] = "Dunkel"
L["With Transparent, the tabs and the step bar stay on screen instead of only under the cursor."] = "Bei Transparent bleiben die Tabs und die Schrittleiste sichtbar, statt nur unter dem Mauszeiger zu erscheinen."
L["With Transparent: Soft lays a light shade behind each line of text, Dark a dark backing behind the whole window. Off: the outlined text alone on the world."] = "Bei Transparent: Weich legt einen leichten Schatten hinter jede Textzeile, Dunkel eine dunkle Unterlegung hinter das ganze Fenster. Aus: nur der umrandete Text über der Welt."
L["Tell me when a newer Polestar is out"] = "Melden, wenn ein neueres Polestar erschienen ist"
L["At login, a card on the guide window says a newer Polestar is out and how to update; Got it keeps it away for a day. A line in the guide window stays until you update. Two or more updates behind, both show even with this off (the card at most once a day)."] = "Beim Einloggen sagt eine Karte am Guide-Fenster, dass ein neueres Polestar erschienen ist und wie du aktualisierst; „Verstanden“ blendet sie für einen Tag aus. Eine Zeile im Guide-Fenster bleibt, bis du aktualisierst. Bist du zwei oder mehr Updates zurück, erscheinen beide auch, wenn das hier aus ist (die Karte höchstens einmal am Tag)."
L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. Guide window in the minimap button's menu, the key binding or /polestar opens it there until you leave."] = "Was das Fenster, seine Buttons und Warnungen in Dungeons, Schlachtzügen, Schlachtfeldern und Arenen tun. „Guide-Fenster“ im Menü des Minikarten-Buttons, die Tastenbelegung oder /polestar öffnet es dort, bis du gehst."
L["A small Polestar button you can put anywhere on the screen. Click to hide or show Polestar, right-click for a menu, drag to move it. It hides with the window in combat and in dungeons when those are set to Hide."] = "Ein kleiner Polestar-Button, den du überall auf dem Bildschirm platzieren kannst. Klicken blendet Polestar aus oder ein, Rechtsklick öffnet ein Menü, Ziehen verschiebt ihn. Er verschwindet mit dem Fenster im Kampf und in Dungeons, wenn diese auf Ausblenden stehen."
L["Hiding Polestar leaves the arrow, its travel button and its arrival sound. This character only."] = "Beim Ausblenden von Polestar bleiben der Pfeil, sein Reise-Button und sein Ankunftston. Nur für diesen Charakter."
L["How near the middle of its spawn area you must be for a suggestion to show. It goes again a little further out."] = "Wie nah du der Mitte seines Spawn-Gebiets sein musst, damit ein Vorschlag erscheint. Etwas weiter draußen verschwindet er wieder."
L["Flight paths you pass"] = "Flugrouten an deinem Weg"
L["Also a friendly flight master near you whose flight path you haven't learned yet. Learning it ticks the guide's later step for it too."] = "Auch ein freundlicher Flugmeister in deiner Nähe, dessen Flugroute du noch nicht kennst. Lernst du sie, wird auch der spätere Schritt des Guides dafür abgehakt."
L["Detour captions"] = "Umweg-Hinweise"
L["Under a walk in the journey, say when it goes round a town of the other faction: \"Detour around Southshore\". It only says so: the route and the arrow stay as they are."] = "Unter einem Fußweg der Reise sagen, wenn er um eine Stadt der anderen Fraktion herumführt: „Umweg um Southshore“. Es ist nur ein Hinweis: Route und Pfeil bleiben, wie sie sind."
L["Manual check-offs and skips, current guide, from your last quest progress on."] = "Manuelle Haken und übersprungene Schritte, aktueller Guide, ab deinem letzten Questfortschritt."
L["Your manual check-offs and skipped steps in %s are cleared from your last quest progress on. Quests you have done stay done, and the guide stays where they put you."] = "Deine manuellen Häkchen und übersprungenen Schritte in %s werden ab deinem letzten Questfortschritt gelöscht. Erledigte Quests bleiben erledigt, und der Guide bleibt dort, wo sie dich hingebracht haben."
L["Your manual check-offs and skipped steps in the current guide are cleared from your last quest progress on. Quests you have done stay done, and the guide stays where they put you."] = "Deine manuellen Häkchen und übersprungenen Schritte im aktuellen Guide werden ab deinem letzten Questfortschritt gelöscht. Erledigte Quests bleiben erledigt, und der Guide bleibt dort, wo sie dich hingebracht haben."
