L["Nothing to pick up before the run: the quests here for you are done, already in your log, or start inside the dungeon or later in their chain."] = "Vor dem Durchlauf ist nichts anzunehmen: Die Quests hier für dich sind erledigt, schon in deinem Questlog oder beginnen im Dungeon oder später in ihrer Questreihe."
