L["You are level %d. Level %d is recommended for the first quest in this chain; from there:"] = "Du bist Stufe %d. Für die erste Quest dieser Questreihe wird Stufe %d empfohlen; ab dort:"
L["%s XP with its chain"] = "%s EP mit ihrer Questreihe"
L["Waiting:"] = "Wartet:"
L["best at %d"] = "am besten bei %d"
L["Tough at your level"] = "Schwer auf eurer Stufe"
-- L["The Dungeons section is turned off. Turn it on under Options > Discovery > Lookup."] = ""

-- UI/Lookup.lua
L["Mount"] = "Reittier"
L["Dungeon"] = "Dungeon"
L["Zone"] = "Gebiet"
L["Treasure"] = "Schatz"
L["Loading the Codex\226\128\166"] = "Der Codex wird geladen…"
L["Lookup is turned off in Options > Discovery > Lookup. Items, mounts, NPCs and quests are not searched."] = "Nachschlagen ist unter Optionen > Entdecken > Nachschlagen ausgeschaltet. Gegenstände, Reittiere, NPCs und Quests werden nicht durchsucht."
L["The Codex loads when combat ends."] = "Der Codex lädt, wenn der Kampf endet."
L["The Codex loads with your first search."] = "Der Codex lädt bei deiner ersten Suche."
L["Search is not part of this Polestar build."] = "Die Suche ist nicht Teil dieser Polestar-Version."
L["The Codex pack could not load (%s)."] = "Das Codex-Paket konnte nicht geladen werden (%s)."
L["Lookup is off: searching guides only"] = "Nachschlagen ist aus: Es werden nur Guides durchsucht"
L["Codex not installed: searching guides only"] = "Codex nicht installiert: Es werden nur Guides durchsucht"
L["Codex disabled: searching guides only"] = "Codex deaktiviert: Es werden nur Guides durchsucht"
L["Codex loads after combat"] = "Der Codex lädt nach dem Kampf"
L["Codex unavailable: searching guides only"] = "Codex nicht verfügbar: Es werden nur Guides durchsucht"
L["g"] = "g"
L["s"] = "s"
L["c"] = "k"
L["< 1 min"] = "< 1 Min."
L["%d min"] = "%d Min."
L["%d h %d min"] = "%d Std. %d Min."
L["%s drop chance"] = "%s Droprate"
L["%s chance"] = "%s Chance"
L["Limited stock"] = "Begrenzter Vorrat"
L["Reward choice"] = "Belohnung zur Wahl"
L["No longer obtainable"] = "Nicht mehr erhältlich"
L["Build a guide to this source and open it in a new tab."] = "Erstellt einen Guide zu dieser Quelle und öffnet ihn in einem neuen Tab."
L["Guide me"] = "Führe mich"
L["Show in Guides"] = "In den Guides zeigen"
L["Category"] = "Kategorie"
L["Faction"] = "Fraktion"
L["Type"] = "Typ"
L["Requires"] = "Benötigt"
L["Elite"] = "Elite"
L["Level"] = "Stufe"
L["%d (from %d)"] = "%d (ab %d)"
L["Raid"] = "Schlachtzug"
L["Sources"] = "Quellen"
L["Places"] = "Orte"
L["None known"] = "Keine bekannt"
L["%d  \194\183  %d open to you"] = "%d  ·  %d für dich offen"
L["Where to get it"] = "Wo du es bekommst"
L["Start and turn-in"] = "Start und Abgabe"
L["Entrance"] = "Eingang"
L["Where to find it"] = "Wo du es findest"
L["Results come in as soon as it is ready."] = "Ergebnisse erscheinen, sobald er bereit ist."
L["Lookup is turned off"] = "Nachschlagen ist ausgeschaltet"
L["The Codex is not loaded"] = "Der Codex ist nicht geladen"
L["Guides are still searched; their results open from here."] = "Guides werden weiterhin durchsucht; ihre Ergebnisse öffnen sich von hier aus."
L["Look something up"] = "Etwas nachschlagen"
L["Type a name: a mount, an item, a pet, an NPC, a quest, a dungeon or a zone. Select a result to see where to get it, best for you first."] = "Gib einen Namen ein: ein Reittier, einen Gegenstand, ein Haustier, einen NPC, eine Quest, einen Dungeon oder ein Gebiet. Wähle ein Ergebnis, um zu sehen, wo du es bekommst, das Beste für dich zuerst."
L["Zones have no sources. Search for what is in them."] = "Gebiete haben keine Quellen. Suche nach dem, was in ihnen ist."
L["Open guide"] = "Guide öffnen"
L["A guide covers this: %s."] = "Ein Guide deckt das ab: %s."
L["Guides from the Codex need the Lookup module."] = "Guides aus dem Codex brauchen das Modul Nachschlagen."
L["Builds a guide to %s, the best source for you, and opens it in a new tab."] = "Erstellt einen Guide zu %s, der besten Quelle für dich, und öffnet ihn in einem neuen Tab."
L["No source is open to this character yet. Pick one above to be guided anyway."] = "Für diesen Charakter ist noch keine Quelle offen. Wähle oben eine, um trotzdem geführt zu werden."
L["The Codex knows no source for this."] = "Der Codex kennt keine Quelle dafür."
L["Open dungeon"] = "Dungeon öffnen"
L["Its quests and bosses are under Dungeons."] = "Seine Quests und Bosse findest du unter Dungeons."
L["Enter does this too."] = "Die Eingabetaste macht das auch."
L["Not open to this character"] = "Für diesen Charakter nicht offen"
L["About %s from here"] = "Etwa %s von hier"
L["Select it, then Guide; or double-click."] = "Wähle es aus und dann „Führe mich“; oder Doppelklick."
L["No guide can lead here."] = "Kein Guide kann hierher führen."
L["No source is known for this yet."] = "Dafür ist noch keine Quelle bekannt."
L["Everything"] = "Alles"
L["Every guide, item, mount, NPC, quest and place, and where to get it."] = "Jeder Guide, Gegenstand, Reittier, NPC, jede Quest und jeder Ort, und wo du es bekommst."
L["1 result for %s"] = "1 Ergebnis für %s"
L["%d results for %s"] = "%d Ergebnisse für %s"
L["Shown for reference: nothing leads to it."] = "Nur zur Information angezeigt: Nichts führt dorthin."
L["Double-click or press Enter to open it in a new tab."] = "Doppelklick oder Eingabetaste öffnet es in einem neuen Tab."
L["Double-click or press Enter to be guided to it."] = "Doppelklick oder Eingabetaste führt dich dorthin."
L["Recent lookups"] = "Zuletzt nachgeschlagen"
L["Show all %d"] = "Alle %d zeigen"
L["Only %s"] = "Nur %s"
L["Show more (%d more)"] = "Mehr zeigen (%d weitere)"
L["The next %d"] = "Die nächsten %d"
L["Type a name in the search box: a mount you saw, an item you want, an NPC or a quest."] = "Gib einen Namen in das Suchfeld ein: ein Reittier, das du gesehen hast, einen Gegenstand, den du willst, einen NPC oder eine Quest."
L["Type a name in the search box to search the guides."] = "Gib einen Namen in das Suchfeld ein, um die Guides zu durchsuchen."
L["Nothing matches %s."] = "Nichts passt zu %s."
L["Lookup is turned off in Options > Discovery > Lookup, so items, mounts, NPCs and quests are not searched."] = "Nachschlagen ist unter Optionen > Entdecken > Nachschlagen ausgeschaltet, daher werden Gegenstände, Reittiere, NPCs und Quests nicht durchsucht."
L["Items, mounts, NPCs and quests are searched once the Codex loads."] = "Gegenstände, Reittiere, NPCs und Quests werden durchsucht, sobald der Codex geladen ist."
L["Search items, mounts, NPCs"] = "Gegenstände, Reittiere, NPCs suchen"
L["Search items, mounts"] = "Gegenstände, Reittiere suchen"
L["In the Codex"] = "Im Codex"
L["Click to see where to get it."] = "Klicken, um zu sehen, wo du es bekommst."
L["Look up everything for %s"] = "Alles zu %s nachschlagen"
L["Opens Lookup with this search."] = "Öffnet Nachschlagen mit dieser Suche."
L["No guide to this mount yet: the sources above say where it comes from and what it takes. Guide on one leads you there."] = "Für dieses Reittier gibt es noch keinen Guide: Die Quellen oben sagen, woher es kommt und was dazu nötig ist. Ein Guide dazu führt dich hin."
L["Origin"] = "Herkunft"
L["Builds a guide to %s, the quickest of these to reach, and opens it in a new tab."] = "Erstellt einen Guide zu %s, dem am schnellsten erreichbaren davon, und öffnet ihn in einem neuen Tab."

-- QoL/Options.lua
L["Off by default: %s does this too."] = "Standardmäßig aus: %s macht das auch."
L["Quest item button"] = "Questgegenstand-Button"
L["Highlight the step's item in your bags"] = "Gegenstand des Schritts in den Taschen hervorheben"
L["Polestar: step item"] = "Polestar: Gegenstand des Schritts"
L["A button for the current step's quest item, with count, cooldown and range. Bind it under Key Bindings > AddOns."] = "Ein Button für den Questgegenstand des aktuellen Schritts, mit Anzahl, Abklingzeit und Reichweite. Belege ihn unter Tastenbelegung > AddOns."
L["Target button"] = "Ziel-Button"
L["Targets the current step's mobs by name, or the NPCs it sends you to when it has no mob; each click moves to the next name. Bindable."] = "Visiert die Mobs des aktuellen Schritts per Name an, oder die NPCs, zu denen er dich schickt, wenn er keinen Mob hat; jeder Klick geht zum nächsten Namen. Belegbar."
L["Show who it targets"] = "Zeigen, wen er anvisiert"
L["The target button's icon shows what you do next: talk, accept, turn in, kill or loot, a skull for an elite, rare or boss, or their face once you have seen them. Their name sits beside it, green for a friendly NPC, red for a mob, gold for an elite or rare, with small icons for the names after it."] = "Das Symbol des Ziel-Buttons zeigt, was du als Nächstes tust: sprechen, annehmen, abgeben, töten oder plündern, ein Totenkopf für Elite, Rare oder Boss, oder ihr Gesicht, sobald du sie gesehen hast. Daneben steht der Name, grün für einen freundlichen NPC, rot für einen Mob, gold für Elite oder Rare, mit kleinen Symbolen für die Namen danach."
L["Name new targets in chat"] = "Neue Ziele im Chat nennen"
L["When the target button's names change, one line in chat lists them (\"Targeting: ...\"). Only you see it."] = "Wenn sich die Namen des Ziel-Buttons ändern, listet eine Chatzeile sie auf (\"Ziel: ...\"). Nur du siehst sie."
L["Targeting: %s"] = "Ziel: %s"
L["Where the target's name shows around the target button: right, left, above or below."] = "Wo der Name des Ziels um den Ziel-Button steht: rechts, links, oben oder unten."
L["Right"] = "Rechts"
L["Left"] = "Links"
L["Above"] = "Oben"
L["Below"] = "Unten"
L["Reset button positions"] = "Button-Positionen zurücksetzen"
L["Put the buttons back in their default spot."] = "Die Buttons an ihre Standardposition zurücksetzen."
L["Mark quest rewards"] = "Quest-Belohnungen markieren"
L["Take the best reward"] = "Beste Belohnung nehmen"
L["Chooses that reward for you when you complete the quest. Hold Shift to choose yourself."] = "Wählt diese Belohnung für dich, wenn du die Quest abschließt. Halte Umschalt gedrückt, um selbst zu wählen."
L["Instant quest text"] = "Sofortiger Questtext"
L["Shows quest text at once instead of fading it in (Forever's own option)."] = "Zeigt den Questtext sofort statt ihn einzublenden (die eigene Option von Forever)."
L["Skip single-option gossip"] = "Gespräche mit nur einer Option überspringen"
L["Faster auto-loot"] = "Schnelleres Automatisch-Plündern"
L["Takes the whole corpse at once when auto-loot is on."] = "Nimmt die ganze Leiche auf einmal, wenn automatisches Plündern an ist."
L["Hide combat errors"] = "Kampffehler ausblenden"
L["Hides \"Not enough rage\", \"Out of range\" and cooldown messages. Other errors still show."] = "Blendet „Nicht genug Wut“, „Außer Reichweite“ und Abklingzeit-Meldungen aus. Andere Fehler werden weiter angezeigt."
L["Open the flight map"] = "Flugkarte öffnen"
L["Talking to a flight master opens the map directly. Hold Shift for the gossip."] = "Das Ansprechen eines Flugmeisters öffnet direkt die Karte. Halte Umschalt gedrückt für das Gespräch."
L["Mark the route's destination"] = "Ziel der Route markieren"
L["Marks where the travel route flies next on the flight map. You still choose the flight."] = "Markiert auf der Flugkarte, wohin die Reiseroute als Nächstes fliegt. Den Flug wählst du weiterhin selbst."
L["Corpse or Spirit Healer"] = "Leiche oder Geistheiler"
L["As a ghost, points the arrow at the faster way back: your corpse or the nearest Spirit Healer."] = "Zeigt als Geist mit dem Pfeil auf den schnelleren Weg zurück: deine Leiche oder den nächsten Geistheiler."
L["Release in battlegrounds"] = "Auf Schlachtfeldern freilassen"
L["Releases your spirit at once when you die in a battleground, unless you can resurrect yourself or someone offers to. Hold Shift to stay."] = "Lässt deinen Geist sofort frei, wenn du auf einem Schlachtfeld stirbst, außer du kannst dich selbst wiederbeleben oder jemand bietet es an. Halte Umschalt gedrückt, um zu bleiben."
L["Accept summons"] = "Beschwörungen annehmen"
L["Takes a summon at once, unless you are in combat. Hold Shift to decide yourself."] = "Nimmt eine Beschwörung sofort an, außer du bist im Kampf. Halte Umschalt gedrückt, um selbst zu entscheiden."
L["Accept resurrections"] = "Wiederbelebungen annehmen"
L["Takes a resurrection as soon as it can, unless the caster is in combat. Never in Hardcore. Hold Shift to decide yourself."] = "Nimmt eine Wiederbelebung an, sobald es geht, außer der Zaubernde ist im Kampf. Nie im Hardcore-Modus. Halte Umschalt gedrückt, um selbst zu entscheiden."
L["Join friends' parties"] = "Gruppen von Freunden beitreten"
L["Accepts party invitations from friends, Battle.net friends and your guild, unless joining would leave a queue. Hold Shift to decide yourself."] = "Nimmt Gruppeneinladungen von Freunden, Battle.net-Freunden und deiner Gilde an, außer der Beitritt würde eine Warteschlange verlassen. Halte Umschalt gedrückt, um selbst zu entscheiden."
L["Decline other party invitations"] = "Andere Gruppeneinladungen ablehnen"
L["Declines party invitations from anyone who is not a friend or in your guild."] = "Lehnt Gruppeneinladungen von allen ab, die kein Freund und nicht in deiner Gilde sind."
L["Decline guild invitations"] = "Gildeneinladungen ablehnen"
L["Declines guild invitations, except from friends."] = "Lehnt Gildeneinladungen ab, außer von Freunden."
L["Decline duels"] = "Duelle ablehnen"
L["Declines duel requests, except from friends and your guild."] = "Lehnt Duellanfragen ab, außer von Freunden und deiner Gilde."
L["Sell grey items"] = "Graue Gegenstände verkaufen"
L["Repair"] = "Reparieren"
L["Repairs all gear at merchants who can, when you can afford it. Hold Shift to skip."] = "Repariert die gesamte Ausrüstung bei Händlern, die es können, wenn du es dir leisten kannst. Halte Umschalt gedrückt, um es auszulassen."
L["Guild bank first"] = "Zuerst die Gildenbank"
L["When your guild rank may, the guild bank pays for repairs and your money covers the rest."] = "Wenn dein Gildenrang es erlaubt, bezahlt die Gildenbank die Reparaturen und dein Geld deckt den Rest."
L["XP tracker"] = "EP-Tracker"
L["XP per hour, time, kills and quests to level, and level splits (/pole xp)."] = "EP pro Stunde, Zeit, Kills und Quests bis zur nächsten Stufe sowie Stufen-Splits (/pole xp)."
L["Reset session"] = "Sitzung zurücksetzen"
L["Start this session's XP per hour from zero."] = "EP pro Stunde dieser Sitzung bei null neu beginnen."
L["Mark what they target"] = "Anvisiertes markieren"
L["A new one each press"] = "Eine neue bei jedem Druck"
L["Icon on mobs"] = "Markierung auf Mobs"
L["A new one each press skips the NPCs' icon and leaves a mob that has one as it is."] = "Eine neue bei jedem Druck überspringt die Markierung der NPCs und lässt einen Mob, der schon eine hat, unverändert."
L["Icon on NPCs"] = "Markierung auf NPCs"
L["A new one each press, so the last few NPCs keep theirs. Every press counts, even one that marks nothing."] = "Eine neue bei jedem Druck, sodass die letzten NPCs ihre behalten. Jeder Druck zählt, auch einer, der nichts markiert."
L["Rare button"] = "Rare-Knopf"
L["Shows a button that targets a rare Polestar spotted nearby, until it dies or is out of sight. Bindable."] = "Zeigt einen Knopf, der eine in der Nähe entdeckte Rare anvisiert, bis sie stirbt oder außer Sicht ist. Kann auf eine Taste gelegt werden."
L["Guide level on the XP bar"] = "Guide-Stufe auf der EP-Leiste"
L["A mark at the end of the game's XP bar with the level the guide wants you to reach before it moves on, and how many levels away that is when it is more than one."] = "Eine Markierung am Ende der EP-Leiste des Spiels mit der Stufe, die du laut Guide erreichen sollst, bevor es weitergeht, und wie viele Stufen das noch sind, wenn es mehr als eine ist."
L["Hearthstone"] = "Ruhestein"
L["Set your home at the guide's inn"] = "Als Zuhause das Gasthaus des Guides setzen"
L["When the step sets your home and you talk to its innkeeper, binds your Hearthstone there. Never at another inn. Hold Shift to skip."] = "Wenn der Schritt dein Zuhause festlegt und du mit dem Gastwirt sprichst, bindet deinen Ruhestein dort. Niemals in einem anderen Gasthaus. Shift gedrückt halten zum Überspringen."
L["Riding reminder"] = "Reit-Erinnerung"
L["At level 40 and 60, if you have not learned riding yet, says the cost in chat (with any Honored discount) and points the arrow at your race's riding trainer when you can afford it. Warlocks and Alliance Paladins are sent to their free-mount quest NPC instead. Once per tier per character."] = "Auf Stufe 40 und 60 sagt es dir im Chat, wenn du das Reiten noch nicht gelernt hast, was es kostet (mit einem eventuellen Rabatt bei Wohlwollend) und richtet den Pfeil auf den Reitlehrer deines Volkes, wenn du es dir leisten kannst. Hexenmeister und Paladine der Allianz werden stattdessen zum NPC ihrer Quest für das kostenlose Reittier geschickt. Einmal pro Stufe und Charakter."
L["Hide the game's quest tracker"] = "Quest-Tracker des Spiels ausblenden"
L["Hides the game's tracker on the right of the screen, with its quests, achievements and professions, as Questie can. Not with the gamepad interface."] = "Blendet den Tracker des Spiels am rechten Bildschirmrand mit seinen Quests, Erfolgen und Berufen aus, wie es Questie kann. Nicht mit der Gamepad-Oberfläche."
L["The item the current step uses, or a quest item it collects, glows in your bags (and in Baganator). An item a later step needs gets a lock, so you don't sell it."] = "Der Gegenstand, den der aktuelle Schritt benutzt, oder ein Questgegenstand, den er sammelt, leuchtet in deinen Taschen (auch in Baganator). Ein Gegenstand, den ein späterer Schritt braucht, bekommt ein Schloss, damit du ihn nicht verkaufst."
L["Offer gear upgrades"] = "Ausrüstungs-Upgrades anbieten"
L["When gear from a kill, a chest or a merchant is an upgrade for your spec (with Gear advice on), the guide window offers to put it on. Nothing goes on until you press Wear it; Not this one stops it asking about that item."] = "Wenn Ausrüstung aus einem Kill, einer Truhe oder von einem Händler ein Upgrade für deine Spezialisierung ist (bei eingeschalteter Ausrüstungsberatung), bietet das Guide-Fenster an, sie anzulegen. Nichts wird angelegt, bevor du „Anlegen“ drückst; „Nicht diesen“ verhindert, dass für diesen Gegenstand noch einmal gefragt wird."
L["Sells Poor-quality items, and anything you marked as junk, when a merchant opens and prints the total. Never an item marked to keep or one a later step needs."] = "Verkauft Gegenstände schlechter Qualität und alles, was du als Plunder markiert hast, wenn ein Händler geöffnet wird, und gibt die Summe aus. Nie einen Gegenstand, der zum Behalten markiert ist oder den ein späterer Schritt braucht."
L["Restock button"] = "Restock-Button"
L["At a merchant that sells what you are short of, a Restock button under its window buys up to the amounts below (this character's). Nothing is bought until you press it. Other items, such as reagents: /polestar restock <item> <amount>."] = "Bei einem Händler, der verkauft, was dir fehlt, kauft ein Restock-Button unter seinem Fenster bis zu den Mengen unten (die dieses Charakters). Gekauft wird erst, wenn du ihn drückst. Andere Gegenstände, etwa Reagenzien: /polestar restock <Gegenstand> <Menge>."
L["Keeps this many drinks in your bags. The merchant's best one for your level is bought."] = "Hält so viele Getränke in deinen Taschen. Das beste des Händlers für deine Stufe wird gekauft."
L["Keeps this much food in your bags. The merchant's best one for your level is bought."] = "Hält so viel Essen in deinen Taschen. Das beste des Händlers für deine Stufe wird gekauft."
L["Keeps this many arrows or shot for the bow, crossbow or gun you wear."] = "Hält so viele Pfeile oder Kugeln für den Bogen, die Armbrust oder das Gewehr, das du trägst."
L["Bags"] = "Taschen"
L["When your bags are nearly full, a button shows the free slots and the cheapest junk in them, and while the step collects something the guide window says so too. Press twice to delete that junk: grey items, or common ones you marked as junk. Bindable."] = "Wenn deine Taschen fast voll sind, zeigt ein Button die freien Plätze und den billigsten Plunder darin, und sammelt der Schritt etwas, sagt das auch das Guide-Fenster. Zweimal drücken löscht diesen Plunder: graue Gegenstände oder gewöhnliche, die du als Plunder markiert hast. Belegbar."
L["Nearly full at"] = "Fast voll bei"
L["%d slot"] = "%d Platz"
L["%d slots"] = "%d Plätze"
L["How many free slots or fewer count as nearly full."] = "Wie viele freie Plätze oder weniger als fast voll gelten."
L["Junk and keep marks"] = "Plunder- und Behalten-Markierungen"
L["Ctrl+Alt-click an item in your bags to mark it as junk, again to keep it, and again to clear it. Junk is sold with the grey items; a kept item is never sold or deleted."] = "Strg+Alt-Klick auf einen Gegenstand in deinen Taschen markiert ihn als Plunder, noch einmal als zu behalten, und noch einmal löscht die Markierung. Plunder wird mit den grauen Gegenständen verkauft; ein Gegenstand zum Behalten wird nie verkauft oder gelöscht."
L["Step key talks and loots"] = "Schrittetaste spricht und plündert"
L["Once the step key has targeted the step's NPC, the next press talks to it; on the corpse of the step's mob, it loots; in the step's quest window, it accepts or completes. Only out of combat, and only on the step the guide is at."] = "Hat die Schrittetaste den NPC des Schritts anvisiert, spricht der nächste Druck mit ihm; beim Leichnam des Mobs des Schritts plündert er; im Questfenster des Schritts nimmt er an oder schließt ab. Nur außerhalb des Kampfs und nur bei dem Schritt, an dem der Guide steht."
L["Warn when out of breath"] = "Bei Atemnot warnen"
L["Under water, a red edge round the screen, a sound and a taskbar flash with 10 seconds of breath left, and again at 4."] = "Unter Wasser erscheinen bei noch 10 Sekunden Atem ein roter Bildschirmrand, ein Ton und ein Aufblinken in der Taskleiste, und noch einmal bei 4."
L["Pick what the step asks for"] = "Wählen, was der Schritt verlangt"
L["At the step's NPC, picks the chat option the guide names, or opens the goods or training the step needs. Only on the step the guide is at. Hold Shift to choose yourself."] = "Beim NPC des Schritts wird die Gesprächsoption gewählt, die der Guide nennt, oder die Waren oder das Training geöffnet, die der Schritt braucht. Nur bei dem Schritt, an dem der Guide steht. Halte Umschalt gedrückt, um selbst zu wählen."
L["Picks the only option of NPCs without quests. Hold Shift to read it. Off, the game still skips some itself, Pick what the step asks for still picks the step's option, and flight masters follow Open the flight map."] = "Wählt die einzige Option von NPCs ohne Quests. Halte Umschalt gedrückt, um sie zu lesen. Aus überspringt das Spiel manche trotzdem selbst, „Wählen, was der Schritt verlangt“ wählt weiter die Option des Schritts, und Flugmeister folgen „Flugkarte öffnen“."
L["Reset"] = "Zurücksetzen"
L["Click objectives to target"] = "Ziele per Klick anvisieren"
L["Clicking an objective row or NPC heading also targets its NPC outside combat, using the same marking settings as the Target button. This replaces your current target; a failed search clears it."] = "Ein Klick auf eine Zielzeile oder eine NPC-Überschrift visiert außerhalb des Kampfes auch den NPC an, mit denselben Markierungseinstellungen wie der Ziel-Button. Das ersetzt dein aktuelles Ziel; eine erfolglose Suche hebt es auf."
L["The target button and the step key put a raid icon on the mob and the NPC they target; out of combat, a press that finds neither clears your target. Pressing again never takes an icon off. In a party you don't lead, only a unit with no icon gets one; in a raid, only when you lead or assist."] = "Der Ziel-Button und die Schrittetaste setzen ein Schlachtzugssymbol auf den Mob und den NPC, die sie anvisieren; außerhalb des Kampfes löscht ein Druck, der keines von beiden findet, dein Ziel. Erneutes Drücken nimmt nie ein Symbol weg. In einer Gruppe, die du nicht führst, bekommt nur eine Einheit ohne Symbol eines; in einem Schlachtzug nur, wenn du führst oder Assistent bist."
L["Ping what they target"] = "Anvisiertes pingen"
L["Show quest-starting loot"] = "Beute anzeigen, die eine Quest startet"
L["When you loot an item that starts a quest you can take, it goes on the quest item button with a glow until you click it or take the quest. The step's own item comes first; several wait their turn, oldest first."] = "Plünderst du einen Gegenstand, der eine Quest startet, die du annehmen kannst, kommt er leuchtend auf den Questgegenstand-Button, bis du ihn anklickst oder die Quest annimmst. Der Gegenstand des Schritts kommt zuerst; mehrere warten, bis sie dran sind, der älteste zuerst."
L["Track only dungeon quests in dungeons"] = "In Dungeons nur Dungeonquests verfolgen"
L["Inside a dungeon or raid, the game's quest tracker and Polestar's quest markers show only that instance's quests. The quests you were tracking come back when you leave, even after a reload inside."] = "In einem Dungeon oder Schlachtzug zeigen der Quest-Tracker des Spiels und die Quest-Markierungen von Polestar nur die Quests dieser Instanz. Die Quests, die du verfolgt hast, kommen zurück, wenn du sie verlässt, auch nach einem Neuladen drinnen."
L["New spells at level-up"] = "Neue Zauber beim Stufenaufstieg"
L["When you level up, a card on the guide window shows the class spells you can now train, what they cost together and the nearest class trainer, with a button for the arrow. Not in combat or instances, and not on levels with nothing new."] = "Bei einem Stufenaufstieg zeigt eine Karte am Guide-Fenster die Klassenzauber, die du jetzt lernen kannst, was sie zusammen kosten und den nächsten Klassenlehrer, mit einem Button für den Pfeil. Nicht im Kampf oder in Instanzen und nicht auf Stufen ohne Neues."
L["Old ranks on your bars"] = "Alte Ränge in deinen Leisten"
L["After training and at login, says which spells on your action bars are a lower rank than the one in your spellbook, with a button that puts the highest rank in the same buttons (out of combat). Macros and items are never touched. Right-click a spell on the card to keep it at its rank; a lower rank you put on a bar yourself is kept too."] = "Sagt nach dem Training und beim Einloggen, welche Zauber in deinen Aktionsleisten einen niedrigeren Rang haben als in deinem Zauberbuch, mit einem Button, der den höchsten Rang auf dieselben Buttons legt (außerhalb des Kampfes). Makros und Gegenstände werden nie angefasst. Rechtsklick auf einen Zauber auf der Karte behält ihn auf seinem Rang; einen niedrigeren Rang, den du selbst in eine Leiste legst, behält es auch."
L["Forget kept ranks"] = "Behaltene Ränge vergessen"
L["Lists the spells you kept at a lower rank again."] = "Listet die Zauber, die du auf einem niedrigeren Rang behalten hast, wieder auf."
L["Boosted Rest status"] = "Anzeige „Verbesserter Ruhebonus“"
L["How long the campfire's Boosted Rest lasts and the Cozy Sleeping Bag's cooldown, under the guide window's XP line; your party's Boosted Rest in the party panel."] = "Wie lange der Verbesserte Ruhebonus des Lagerfeuers noch anhält und die Abklingzeit des Gemütlichen Schlafsacks, unter der EP-Zeile des Guide-Fensters; den Verbesserten Ruhebonus deiner Gruppe im Gruppenfenster."
L["Take the marked flight"] = "Markierten Flug nehmen"
L["When the flight map opens, flies to the marked destination. Hold Shift at the flight master to choose yourself."] = "Fliegt zum markierten Ziel, wenn sich die Flugkarte öffnet. Halte beim Flugmeister Umschalt gedrückt, um selbst zu wählen."
-- L["Open"] = ""
-- L["Button look"] = ""
-- L["Size, spacing, layout, backing, text, opacity and glow of these buttons, with a live preview, on the Buttons page."] = ""
-- L["Targeting"] = ""
-- L["Quest log and tooltips"] = ""
-- L["Rewards, buttons and tracker"] = ""
L["Your Hearthstone in the action button set, beside the quest item and target buttons, while the guide says to hearth. Bindable. The travel button under the arrow is a switch of its own: turning this one off leaves that one on."] = "Dein Ruhestein bei den Aktions-Buttons, neben dem Questgegenstand- und dem Ziel-Button, solange der Guide dich zum Ruhestein schickt. Belegbar. Der Reise-Button unter dem Pfeil hat einen eigenen Schalter: Schaltest du diesen hier aus, bleibt jener an."
L["Under the arrow, while the route's next leg is your Hearthstone, a teleport or a portal: a button that casts it. Right-click the arrow to skip the leg. The Hearthstone in the button set is a switch of its own: turning this one off leaves that one on."] = "Unter dem Pfeil, solange die nächste Etappe der Route dein Ruhestein, ein Teleport oder ein Portal ist: ein Button, der ihn wirkt. Rechtsklick auf den Pfeil überspringt die Etappe. Der Ruhestein bei den Aktions-Buttons hat einen eigenen Schalter: Schaltest du diesen hier aus, bleibt jener an."
L["Hearthstone in the button set"] = "Ruhestein bei den Aktions-Buttons"
L["Travel button under the arrow"] = "Reise-Button unter dem Pfeil"
