L["Watch for rare NPCs and treasures and keep when you last met them (/pole rares). Their map pins are under Map, off by default."] = "Hält nach seltenen NPCs und Schätzen Ausschau und merkt sich, wann du ihnen zuletzt begegnet bist (/pole rares). Ihre Kartenmarkierungen findest du unter Karte, standardmäßig aus."
L["Alert for rares"] = "Alarm bei Rares"
L["A card with its name, level and distance, and a waypoint to it."] = "Eine Karte mit Name, Stufe und Entfernung sowie ein Wegpunkt dorthin."
L["Alert for treasures"] = "Alarm bei Schätzen"
L["Treasures the client marks on the minimap."] = "Schätze, die der Client auf der Minikarte markiert."
L["Once per rare every"] = "Einmal pro Rare alle"
L["The same rare stays quiet this long after an alert."] = "Dasselbe Rare bleibt nach einem Alarm so lange still."
