L["Minimap markers"] = "Minikarten-Markierungen"
L["Rares and treasures the client marks on the minimap (vignettes), with their exact distance."] = "Rares und Schätze, die der Client auf der Minikarte markiert (Vignetten), mit ihrer genauen Entfernung."
L["Nameplates"] = "Namensplaketten"
L["A rare's nameplate coming into view. Needs enemy nameplates on."] = "Die Namensplakette eines Rares kommt ins Bild. Erfordert eingeschaltete Gegner-Namensplaketten."
L["Your target"] = "Dein Ziel"
L["Targeting a rare."] = "Ein Rare anvisieren."
L["Under the cursor"] = "Unter dem Mauszeiger"
L["Pointing at a rare in the world."] = "Mit der Maus auf ein Rare in der Welt zeigen."
L["Rares on the world map"] = "Rares auf der Weltkarte"
L["Every known spawn point. Click one to see it in Rares; Shift-click for a waypoint."] = "Jeder bekannte Spawnpunkt. Klicke einen an, um ihn in Rares zu sehen; Umschalt-Klick setzt einen Wegpunkt."
L["Treasures on the world map"] = "Schätze auf der Weltkarte"
L["Every known treasure spot."] = "Jeder bekannte Schatzort."
L["Rares on the minimap"] = "Rares auf der Minikarte"
L["Loads the Codex at login."] = "Lädt den Codex beim Einloggen."
L["Treasures on the minimap"] = "Schätze auf der Minikarte"
L["Hide rares below your level"] = "Rares unter deiner Stufe ausblenden"
L["Rares too low to give experience leave the map."] = "Rares, die zu niedrig für Erfahrung sind, verschwinden von der Karte."
L["Forget rares met on this realm"] = "Auf diesem Realm getroffene Rares vergessen"
L["Clears the Seen list, alert cooldowns and the glow on recently seen pins."] = "Leert die Liste „Gesehen“, die Alarm-Pausen und das Leuchten auf kürzlich gesehenen Markierungen."
L["Say when Polestar's founder is nearby"] = "Melden, wenn der Gründer von Polestar in der Nähe ist"
L["When %s comes into sight, a card says so and the rare button targets him and waves. At most once a day, never in combat or instances."] = "Wenn %s in Sicht kommt, sagt es eine Karte, und der Rare-Knopf visiert ihn an und winkt. Höchstens einmal am Tag, nie im Kampf oder in Instanzen."

-- Maps/Maps.lua
L["Dungeon entrances"] = "Dungeon-Eingänge"
L["Marks each dungeon entrance with its level range. Click to open the dungeon's guide, or to set a waypoint when there is none; Shift-click always sets a waypoint. Needs the Codex pack."] = "Markiert jeden Dungeon-Eingang mit seiner Stufenspanne. Klicke, um den Guide des Dungeons zu öffnen, oder um einen Wegpunkt zu setzen, wenn es keinen gibt; Umschalt-Klick setzt immer einen Wegpunkt. Erfordert das Codex-Paket."
L["Your faction's and neutral flight masters: green when known, amber when not yet discovered. The tooltip lists destinations and flight times."] = "Flugmeister deiner Fraktion und neutrale: grün, wenn bekannt, bernsteinfarben, wenn noch nicht entdeckt. Der Tooltip listet Ziele und Flugzeiten."
L["Boats and zeppelins"] = "Boote und Zeppeline"
L["Docks, zeppelin towers and the Deeprun Tram, with where they go."] = "Anlegestellen, Zeppelintürme und die Tiefenbahn, mit ihren Zielen."
L["Inns"] = "Gasthäuser"
L["Innkeepers; the one your Hearthstone is bound to is marked."] = "Gastwirte; der, an den dein Ruhestein gebunden ist, ist markiert."
L["Travel icons on the minimap"] = "Reisesymbole auf der Minikarte"
L["Shows the flight masters, docks and inns turned on here on the minimap as well."] = "Zeigt die hier eingeschalteten Flugmeister, Anlegestellen und Gasthäuser auch auf der Minikarte."
L["Unexplored areas"] = "Unerforschte Gebiete"
L["Shows the parts of each zone you have not explored yet, so the whole map is there before you visit. Tinted keeps them apart from where you have been."] = "Zeigt die Teile jedes Gebiets, die du noch nicht erkundet hast, damit die ganze Karte schon vor deinem Besuch da ist. „Getönt“ hält sie von den bereisten Teilen getrennt."
L["Hidden"] = "Verborgen"
L["Revealed"] = "Aufgedeckt"
L["Revealed and tinted"] = "Aufgedeckt und getönt"
L["Zone level ranges"] = "Stufenspannen der Gebiete"
L["Shows each zone's level range on the continent and zone maps, coloured by difficulty for your level."] = "Zeigt die Stufenspanne jedes Gebiets auf den Kontinent- und Gebietskarten, nach Schwierigkeit für deine Stufe eingefärbt."
L["Shows your position and the cursor's position under the world map."] = "Zeigt deine Position und die des Mauszeigers unter der Weltkarte."
L["Coordinates on the minimap"] = "Koordinaten auf der Minikarte"
L["A small readout of your position at the bottom of the minimap."] = "Eine kleine Anzeige deiner Position am unteren Rand der Minikarte."
L["While flying, shows the destination and the time left. Learns each route's real duration for this character; drag to move."] = "Zeigt beim Fliegen das Ziel und die verbleibende Zeit. Lernt die tatsächliche Dauer jeder Route für diesen Charakter; zum Verschieben ziehen."
L["Forget learned flight times"] = "Gelernte Flugzeiten vergessen"
L["Clears this character's recorded flight durations; estimates are used until they are flown again."] = "Löscht die aufgezeichneten Flugdauern dieses Charakters; bis sie wieder geflogen werden, gelten Schätzungen."
L["Learned flight times cleared."] = "Gelernte Flugzeiten gelöscht."
L["Track instances"] = "Instanzen verfolgen"
L["Records dungeon and raid entries, time and experience per run. /pole instances lists them."] = "Zeichnet Dungeon- und Schlachtzug-Eintritte, Zeit und Erfahrung pro Durchlauf auf. /pole instances listet sie auf."
L["Compact display"] = "Kompakte Anzeige"
L["Shows the hourly instance count and the current run while it matters; drag to move."] = "Zeigt die Instanzanzahl pro Stunde und den aktuellen Durchlauf, solange es darauf ankommt; zum Verschieben ziehen."
L["Instances per hour"] = "Instanzen pro Stunde"
L["Classic allows 5 new instances per hour per account. Forever may differ; adjust if it does."] = "Classic erlaubt 5 neue Instanzen pro Stunde und Account. Forever kann abweichen; passe es an, wenn es so ist."
L["Instances per day"] = "Instanzen pro Tag"
L["Classic Era allows 30 new instances per 24 hours per account; 0 ignores the daily cap. Forever may differ."] = "Classic Era erlaubt 30 neue Instanzen pro 24 Stunden und Account; 0 ignoriert die Tagesgrenze. Forever kann abweichen."
L["Clear instance history"] = "Instanzverlauf löschen"
L["Forgets recorded entries and runs (the server's own limit is not affected)."] = "Vergisst aufgezeichnete Eintritte und Durchläufe (die eigene Grenze des Servers bleibt unberührt)."
L["Minimap button"] = "Minikarten-Button"
L["Forget"] = "Vergessen"
L["Clear"] = "Leeren"
L["Minimap"] = "Minikarte"
L["A Polestar button on the edge of the minimap. Click to hide or show Polestar, right-click for a menu, drag to move it."] = "Ein Polestar-Button am Rand der Minikarte. Klicken blendet Polestar aus oder ein, Rechtsklick öffnet ein Menü, Ziehen verschiebt ihn."

-- Quests/Options.lua
L["Any level"] = "Jede Stufe"
L["Quest, NPC and item data for markers and tooltips, loaded when one of them is on (about 5 MB of memory)."] = "Quest-, NPC- und Gegenstandsdaten für Markierungen und Tooltips, geladen, wenn eine davon an ist (etwa 5 MB Speicher)."
L["Available quests"] = "Verfügbare Quests"
L["Mark quest givers with quests you can accept now."] = "Markiert Questgeber mit Quests, die du jetzt annehmen kannst."
L["Quests above your level"] = "Quests über deiner Stufe"
L["Mark quests up to this many levels above yours."] = "Markiert Quests bis zu dieser Zahl von Stufen über deiner."
L["Low-level quests"] = "Quests niedriger Stufe"
L["Also mark grey quests that are far below your level."] = "Markiert auch graue Quests, die weit unter deiner Stufe liegen."
L["World map objectives"] = "Ziele auf der Weltkarte"
L["Mark mob areas, item sources and objects for quests in your log."] = "Markiert Mob-Gebiete, Gegenstandsquellen und Objekte für Quests in deinem Questlog."
L["Turn-ins"] = "Abgaben"
L["Mark who to return to once a quest is ready."] = "Markiert, zu wem du zurückkehren musst, sobald eine Quest fertig ist."
L["Show the same quest markers on the minimap."] = "Zeigt dieselben Quest-Markierungen auf der Minikarte."
L["Highlight step quests"] = "Quests des Schritts hervorheben"
L["Enlarge and light up the markers of the quests in your guide's current step."] = "Vergrößert und beleuchtet die Markierungen der Quests im aktuellen Schritt deines Guides."
L["Dim other quests"] = "Andere Quests abdunkeln"
L["While a guide runs, fade every quest marker that is not part of its current step."] = "Blendet, solange ein Guide läuft, jede Quest-Markierung aus, die nicht zum aktuellen Schritt gehört."
L["Quest tooltips"] = "Quest-Tooltips"
L["Name the quests a mob, item or object is for, with your progress."] = "Nennt die Quests, für die ein Mob, Gegenstand oder Objekt gebraucht wird, mit deinem Fortschritt."
L["Nameplate icons"] = "Namensplaketten-Symbole"
L["Show a quest icon and your progress, like 3/10, on nameplates of mobs you still need."] = "Zeigt ein Quest-Symbol mit deinem Fortschritt, etwa 3/10, auf den Namensplaketten von Mobs, die du noch brauchst."
L["Quest levels"] = "Quest-Stufen"
L["Show quest levels, like [12], wherever the game lists quests without them."] = "Zeigt Quest-Stufen wie [12] überall, wo das Spiel Quests ohne sie auflistet."
L["Quest database is off."] = "Die Quest-Datenbank ist aus."
L["Quest database not installed (Polestar_QuestDB)."] = "Quest-Datenbank nicht installiert (Polestar_QuestDB)."
L["quests"] = "Quests"
L["available now"] = "jetzt verfügbar"
L["mobs tracked"] = "Mobs erfasst"
L["Quest database status"] = "Status der Quest-Datenbank"
L["Quest marks in bags"] = "Quest-Markierungen in den Taschen"
L["Mark bag items a quest still needs, in your log or ahead in your guide, until you hand the quest in."] = "Markiert Gegenstände in den Taschen, die eine Quest noch braucht, in deinem Questlog oder weiter vorn in deinem Guide, bis du die Quest abgibst."
L["Offer to buy back quest items"] = "Rückkauf von Questgegenständen anbieten"
L["If you sell an item a quest still needs, ask whether to buy it back from the vendor."] = "Verkaufst du einen Gegenstand, den eine Quest noch braucht, wird gefragt, ob du ihn vom Händler zurückkaufen willst."
L["Nameplate icon position"] = "Position der Namensplaketten-Symbole"
L["Where the quest icon and your progress sit on a nameplate: left or right of the health bar, or above the name. Move them if another addon's icon covers them."] = "Wo das Quest-Symbol und dein Fortschritt auf einer Namensplakette sitzen: links oder rechts vom Lebensbalken oder über dem Namen. Verschiebe sie, wenn das Symbol eines anderen Addons sie verdeckt."
L["Objective spots on the map"] = "Zielorte auf der Karte"
L["A goal's spots close together can draw as one shaded area with one marker in the middle, so the map stays readable."] = "Die Orte eines Ziels, die nah beieinander liegen, können als eine schattierte Fläche mit einer Markierung in der Mitte gezeichnet werden, damit die Karte lesbar bleibt."
L["Areas for groups"] = "Flächen für Gruppen"
L["Icons only"] = "Nur Symbole"
L["Areas only"] = "Nur Flächen"
L["Area opacity"] = "Deckkraft der Flächen"
L["How strongly the objective areas tint the map."] = "Wie stark die Zielflächen die Karte einfärben."
L["Quest marker size"] = "Größe der Questmarkierungen"
L["The size of every quest marker on the world map and the minimap."] = "Die Größe jeder Questmarkierung auf der Weltkarte und der Minikarte."
L["Timed quest alerts"] = "Warnungen für Zeitquests"
L["A chat line and a sound when a timed quest has 5 minutes left, again at 1 minute, and if it fails. The guide window always shows the time left."] = "Eine Chatzeile und ein Ton, wenn eine Zeitquest noch 5 Minuten hat, erneut bei 1 Minute und wenn sie fehlschlägt. Das Leitfadenfenster zeigt die verbleibende Zeit immer an."
