L["No community addons installed."] = "Keine Community-Addons installiert."
L["Suggestions"] = "Vorschläge"
L["Suggest guides from"] = "Guides vorschlagen aus"
L["Where the guide for your level is suggested from. Polestar's guides fill in where a community addon has none for you."] = "Woher der Guide für deine Stufe vorgeschlagen wird. Polestars Guides springen ein, wo ein Community-Addon keinen für dich hat."
L["About community guides"] = "Über Community-Guides"
L["A community addon is a separate addon with someone else's guides for Polestar. It is not part of Polestar, and its guides are not Polestar's own routes."] = "Ein Community-Addon ist ein eigenes Addon mit Guides von jemand anderem für Polestar. Es ist nicht Teil von Polestar, und seine Guides sind nicht Polestars eigene Routen."
L["Get a community addon from wherever its author publishes it and install it like any addon, then restart the game. Its guides appear in the guide menu under Community guides, with the author's name. The switch on its row above turns it on or off."] = "Hol dir ein Community-Addon dort, wo sein Autor es veröffentlicht, und installiere es wie jedes Addon, dann starte das Spiel neu. Seine Guides erscheinen im Guide-Menü unter Community-Guides, mit dem Namen des Autors. Der Schalter in seiner Zeile oben schaltet es ein oder aus."
L["Each community addon is made and supported by its author: report its problems to them, not to Polestar. It is an addon like any other, so install community addons from authors you trust."] = "Jedes Community-Addon wird von seinem Autor erstellt und betreut: Melde seine Probleme ihm, nicht Polestar. Es ist ein Addon wie jedes andere, installiere Community-Addons also nur von Autoren, denen du vertraust."
L["Anyone can make a community addon with Polestar's own tools."] = "Jeder kann mit Polestars eigenen Werkzeugen ein Community-Addon erstellen."
L["Community guides, explained"] = "Community-Guides erklärt"
L["Installed"] = "Installiert"
L["Read more:"] = "Mehr dazu:"
L["Read more: docs/GUIDE_PACKS.md in Polestar's source"] = "Mehr dazu: docs/GUIDE_PACKS.md im Quellcode von Polestar"
L["Community addon: %s (%s)"] = "Community-Addon: %s (%s)"
L["Community addon version: %s"] = "Version des Community-Addons: %s"
L["Polestar version: %s"] = "Polestar-Version: %s"
L["Client build: %s (%s)"] = "Client-Build: %s (%s)"
L["Problems:"] = "Probleme:"
L["Turn on and reload"] = "Einschalten und neu laden"
L["Polestar Guides is turned off in the AddOns list, so Polestar has no guides to show. Turn it on for all your characters and reload?"] = "Polestar Guides ist in der AddOn-Liste ausgeschaltet, daher hat Polestar keine Guides zum Anzeigen. Für alle deine Charaktere einschalten und neu laden?"

-- UI/Report.lua (the report text itself stays English: the maintainers read it)
