L["Report problems, ask for help and hear about new guides first. The invite is selected for you: copy it with Ctrl+C (Cmd+C on a Mac) and open it in your browser."] = "Melde Probleme, frag nach Hilfe und erfahre als Erstes von neuen Guides. Die Einladung ist für dich markiert: Kopiere sie mit Strg+C (Cmd+C auf dem Mac) und öffne sie in deinem Browser."
