L["Say what went wrong first."] = "Schreib zuerst, was schiefging."
L["Open on GitHub"] = "Auf GitHub öffnen"
L["The link is selected for you: copy it with Ctrl+C (Cmd+C on a Mac), paste it in your browser's address bar, check the form and press Create."] = "Der Link ist bereits markiert: Kopiere ihn mit Strg+C (Cmd+C auf dem Mac), füge ihn in die Adressleiste deines Browsers ein, prüfe das Formular und drück auf „Create“."
L["Mark here"] = "Hier markieren"
L["Cancel"] = "Abbrechen"
L["Walk to where the step should have sent you: the NPC, the object or the mobs as you found them. Then press Mark here. Your report is kept while you walk."] = "Geh dorthin, wohin dich der Schritt hätte schicken sollen: zum NPC, zum Objekt oder zu den Mobs, wie du sie vorgefunden hast. Drück dann auf „Hier markieren“. Dein Bericht bleibt erhalten, während du gehst."
L["Clear mark"] = "Markierung entfernen"
L["Report it on Discord"] = "Auf Discord melden"
L["1. Press Copy report, then Ctrl+C (Cmd+C on a Mac).\n2. In the Polestar Discord, open #bugs and press New Post. Not in it yet? Get the invite.\n3. Paste the report, give it a short title and post it. A bot files it for the developers and tells you in your thread when it's fixed."] = "1. Drück auf „Bericht kopieren“, dann Strg+C (Cmd+C auf dem Mac).\n2. Öffne im Polestar-Discord #bugs und drück auf „New Post“. Noch nicht dabei? Hol dir die Einladung.\n3. Füge den Bericht ein, gib ihm einen kurzen Titel und poste ihn. Ein Bot meldet ihn den Entwicklern und sagt dir in deinem Thread Bescheid, wenn er behoben ist."
L["Have a GitHub account? Open the issue there with everything filled in."] = "Du hast ein GitHub-Konto? Öffne das Issue dort, komplett ausgefüllt."
