L["Reward pick in the guide"] = "Belohnungswahl im Guide"
L["Under a turn-in step, name the reward to take: an upgrade with its gain, else the best one you can use. The marks on the game's reward panel are under Quest rewards."] = "Nennt unter einem Abgabeschritt die Belohnung, die du nehmen solltest: ein Upgrade mit seinem Gewinn, sonst die beste, die du benutzen kannst. Die Markierungen im Belohnungsfenster des Spiels findest du unter Quest-Belohnungen."
L["Reward pick on tooltips"] = "Belohnungswahl auf Tooltips"
