-- Quests/Party.lua
L["%s done"] = "%s fertig"
L["Not on this quest: %s"] = "Nicht auf dieser Quest: %s"
L["Party"] = "Gruppe"
L["Share my quest progress with my party"] = "Meinen Questfortschritt mit meiner Gruppe teilen"
L["Show my party's progress in the guide"] = "Den Fortschritt meiner Gruppe im Guide zeigen"
L["%s has a newer %s guide pack (%s; yours is %s)."] = "%s hat ein neueres Guide-Paket %s (%s; deins ist %s)."
L["%s: 1 step ahead"] = "%s: 1 Schritt voraus"
L["%s: %d steps ahead"] = "%s: %d Schritte voraus"
L["%s: 1 step behind"] = "%s: 1 Schritt zurück"
L["%s: %d steps behind"] = "%s: %d Schritte zurück"
L["%s: on this step"] = "%s: bei diesem Schritt"
L["Still at it: %s"] = "Noch dran: %s"
L["already done"] = "schon erledigt"
L["quest log full"] = "Questlog voll"
L["can't take it"] = "kann sie nicht annehmen"
L["too far to share"] = "zum Teilen zu weit weg"
L["level too low"] = "Stufe zu niedrig"
L["another class"] = "andere Klasse"
L["another race"] = "anderes Volk"
L["level %d, needs %d"] = "Stufe %d, braucht %d"
L["Waiting on %s"] = "Warte auf %s"
L["Everyone's ready"] = "Alle sind bereit"
L["Waiting on %s: %s"] = "Warte auf %s: %s"
L["%s still needs %d %s"] = "%s braucht noch %d %s"
L["%s (%s)"] = "%s (%s)"
L["%s: other guide"] = "%s: anderer Guide"
L["Party: %s"] = "Gruppe: %s"
L["For %s: she still needs %d"] = "Für %s: Sie braucht noch %d"
L["For %s: he still needs %d"] = "Für %s: Er braucht noch %d"
L["For %s: still needs %d"] = "Für %s: braucht noch %d"
L["Party members who run Polestar see your counts under their quest goals, your step and your level. Hidden addon messages to your party only; nothing goes to chat."] = "Gruppenmitglieder, die Polestar nutzen, sehen deine Zählstände unter ihren Questzielen, deinen Schritt und deine Stufe. Versteckte Addon-Nachrichten nur an deine Gruppe; nichts geht in den Chat."
L["Their counts under your quest goals, and who lacks a quest you took, with a Share button."] = "Ihre Zählstände unter deinen Questzielen und wem eine Quest fehlt, die du angenommen hast, mit einem Knopf zum Teilen."
L["Wait for the group"] = "Auf die Gruppe warten"
L["When a party member on your quest still needs an objective you finished, the step and its turn-in wait and the arrow leads to what they need. Members in another zone or offline for 2 minutes don't hold you; the party line offers Go on without them."] = "Braucht ein Gruppenmitglied auf deiner Quest noch ein Ziel, das du erledigt hast, warten der Schritt und seine Abgabe, und der Pfeil führt zu dem, was es noch braucht. Mitglieder in einem anderen Gebiet oder seit 2 Minuten offline halten dich nicht auf; die Gruppenzeile bietet „Ohne sie weiter“."
L["Say who still needs quest loot"] = "Sagen, wer noch Questbeute braucht"
L["On a loot window or roll, a line under a quest item a party member still needs and you don't. Nothing is passed or said for you."] = "Im Beutefenster oder bei einem Wurf eine Zeile zu einem Questgegenstand, den ein Gruppenmitglied noch braucht und du nicht. Nichts wird für dich gepasst oder gesagt."
L["Party panel"] = "Gruppenfenster"
L["Opens by itself when someone in your party runs Polestar too: each member's level, step and what they still need of yours; click a name to point the arrow at them. Closed, it stays closed; /polestar party opens it again."] = "Öffnet sich von selbst, wenn jemand in deiner Gruppe ebenfalls Polestar nutzt: Stufe und Schritt jedes Mitglieds und was es noch von dir braucht; klicke auf einen Namen, um den Pfeil auf diese Person zu richten. Einmal geschlossen, bleibt es zu; /polestar party öffnet es wieder."
L["Tell my party about objectives and ready quests"] = "Meiner Gruppe Questziele und abgabebereite Quests sagen"
L["A party chat line with the quest's link when you finish its objectives, and one when the quest is ready to turn in. Everyone in the party sees it, Polestar or not. Never solo or in a raid."] = "Eine Zeile im Gruppenchat mit dem Link der Quest, wenn du ihre Ziele erledigst, und eine, wenn die Quest abgegeben werden kann. Die ganze Gruppe sieht sie, mit oder ohne Polestar. Nie allein oder im Schlachtzug."
L["Tell my party when I loot an item that starts a quest"] = "Meiner Gruppe sagen, wenn ich einen Gegenstand erbeute, der eine Quest startet"
L["A party chat line with the item's link and the quest it starts."] = "Eine Zeile im Gruppenchat mit dem Link des Gegenstands und der Quest, die er startet."
L["Show my own lines in my chat too"] = "Meine eigenen Zeilen auch in meinem Chat zeigen"
L["Off: your party sees the lines Polestar says for you, and your chat stays clear of them."] = "Aus: Deine Gruppe sieht die Zeilen, die Polestar für dich sagt, und dein Chat bleibt frei davon."
L["Hide other players' Polestar lines"] = "Polestar-Zeilen anderer Spieler ausblenden"
L["Party members' Polestar lines leave your chat. Shown, they carry Polestar's star."] = "Die Polestar-Zeilen deiner Gruppenmitglieder verschwinden aus deinem Chat. Sichtbar tragen sie den Stern von Polestar."
L["Only when someone in the party doesn't have Polestar"] = "Nur wenn jemand in der Gruppe Polestar nicht hat"
L["Nothing goes to chat while everyone in your party runs Polestar: they see your progress in their guide."] = "Nichts geht in den Chat, solange alle in deiner Gruppe Polestar nutzen: Sie sehen deinen Fortschritt in ihrem Guide."
L["%s asks you to sync to their guide."] = "%s bittet dich, dich mit seinem Guide zu synchronisieren."
L["You'll switch to %s."] = "Du wechselst zu %s."
L["Their step: %s"] = "Sein Schritt: %s"
L["You're past their step: your guide stays where you are."] = "Du bist schon über seinen Schritt hinaus: Dein Guide bleibt, wo du bist."
L["%s is past these, which you haven't done: %s"] = "%s ist schon über diese hinaus, die du noch nicht erledigt hast: %s"
L["You've done these already, so your guide passes them: %s"] = "Diese hast du schon erledigt, daher überspringt dein Guide sie: %s"
L["%s asked you to sync to their guide, but it isn't for your character or your copy lacks their step."] = "%s hat dich gebeten, dich mit seinem Guide zu synchronisieren, aber er passt nicht zu deinem Charakter oder deiner Version fehlt sein Schritt."
L["No room for another guide tab: close one, then ask %s again."] = "Kein Platz für einen weiteren Guide-Tab: Schließ einen und frag dann %s erneut."
L["%s synced to your guide."] = "%s hat sich mit deinem Guide synchronisiert."
L["%s declined to sync."] = "%s hat die Synchronisierung abgelehnt."
L["%s can't sync: your guide isn't for their character, or their copy lacks your step."] = "%s kann nicht synchronisieren: Dein Guide passt nicht zu seinem Charakter, oder seiner Version fehlt dein Schritt."
L["%s is already on your step."] = "%s ist bereits bei deinem Schritt."
L["No one else in your party has been heard running Polestar yet."] = "Von niemandem sonst in deiner Gruppe wurde bisher Polestar erkannt."
L["You have no step to sync to: open a guide you haven't finished."] = "Du hast keinen Schritt zum Synchronisieren: Öffne einen Guide, den du noch nicht abgeschlossen hast."
L["You asked a moment ago: wait %d seconds."] = "Du hast gerade erst gefragt: Warte %d Sekunden."
L["The game didn't send it: try again in a moment."] = "Das Spiel hat es nicht gesendet: Versuch es gleich noch einmal."
L["Asked your party to sync to your step. Each of them chooses."] = "Deine Gruppe wurde gebeten, sich mit deinem Schritt zu synchronisieren. Jeder entscheidet selbst."
L["%s asked you to sync to their guide; that prompt can't show with the gamepad interface."] = "%s hat dich gebeten, dich mit seinem Guide zu synchronisieren; diese Abfrage kann mit der Gamepad-Oberfläche nicht angezeigt werden."
L["%s is on Polestar %s: your guides can differ. A newer version is out."] = "%s nutzt Polestar %s: Eure Guides können sich unterscheiden. Eine neuere Version ist erschienen."
L["%s is on Polestar %s: your guides can differ."] = "%s nutzt Polestar %s: Eure Guides können sich unterscheiden."
L["Party sync is on: you and your party see each other's quest progress. Turn it off in Options."] = "Der Gruppenabgleich ist an: Du und deine Gruppe seht gegenseitig euren Questfortschritt. Ausschalten kannst du ihn in den Optionen."
L["Ask other players' Polestar which version it is"] = "Das Polestar anderer Spieler nach seiner Version fragen"
L["Up to 10 hidden addon whispers a session, to players of your faction you target or mouse over outside cities, combat and dungeons, and an answer to theirs: only the version number, so Polestar can tell you when a newer one is out. Off: none sent or answered."] = "Bis zu 10 versteckte Addon-Flüsternachrichten pro Sitzung an Spieler deiner Fraktion, die du außerhalb von Städten, Kämpfen und Dungeons anvisierst oder mit der Maus berührst, und eine Antwort auf ihre: nur die Versionsnummer, damit Polestar dir sagen kann, wenn eine neuere erschienen ist. Aus: Es wird nichts gesendet oder beantwortet."
-- L["Your party is running %s: run it with them?"] = ""
-- L["Run it this time"] = ""
-- L["%s asked you to sync to their run of %s, but your route has passed it or your character is below its level."] = ""

