L["Show planned turn-ins in Questie"] = "Geplante Abgaben in Questie zeigen"
L["Completed quests in Questie's tracker show their Polestar turn-in step. Earlier, skipped and unplanned hand-ins are flagged."] = "Abgeschlossene Quests in Questies Tracker zeigen ihren Polestar-Abgabeschritt. Frühere, übersprungene und ungeplante Abgaben werden markiert."

-- Talents/Builds.lua
L["Holy"] = "Heilig"
L["Protection"] = "Schutz"
L["Level as Retribution (quickest solo, with a two-hander and Seal of Command) or Protection (safe group pulls, dungeon-tank ready). Holy suits raids; it can level through its melee build, more slowly, if you want to heal dungeons on the way."] = "Levle als Vergeltung (am schnellsten solo, mit Zweihandwaffe und Siegel des Befehls) oder Schutz (sichere Gruppen-Pulls, bereit als Dungeon-Tank). Heilig passt zu Schlachtzügen; es kann über seinen Nahkampf-Build leveln, langsamer, wenn du unterwegs Dungeons heilen willst."
L["Start with Divine Intellect: more mana means you can melee and still cover your own (or a group's) healing."] = "Beginne mit Göttlicher Weisheit: Mehr Mana heißt, du kannst im Nahkampf kämpfen und trotzdem deine eigene (oder die einer Gruppe) Heilung abdecken."
L["Improved Seals raises every seal and Judgement here, which is where Holy's leveling damage comes from."] = "Verbesserte Siegel verstärkt hier jedes Siegel und jedes Richturteil, und daher kommt der Levelschaden von Heilig."
L["Reverence keeps a trickle of regen going while casting; three ranks unlock Illumination."] = "Andacht hält beim Zaubern einen Rest an Regeneration aufrecht; drei Ränge schalten Illumination frei."
L["Illumination refunds mana on critical heals and is the heart of Holy's staying power."] = "Illumination erstattet Mana bei kritischen Heilungen und ist das Herzstück der Ausdauer von Heilig."
L["Holy Shock is a talent on Forever: an instant heal or Holy hit, handy for emergencies and for pulling."] = "Heiliger Schock ist auf Forever ein Talent: eine Sofortheilung oder ein Heiligtreffer, praktisch für Notfälle und zum Pullen."
L["Holy Power raises Holy Shock's crit chance, feeding Illumination and Infusion of Light."] = "Heilige Kraft erhöht die Crit-Chance des Heiligen Schocks und speist Illumination und Lichtinfusion."
L["Light's Vigil turns Holy Shock into a group-heal burst; this is the signature Forever Holy talent."] = "Lichtwacht macht aus dem Heiligen Schock einen Gruppenheilungs-Stoß; es ist das typische Forever-Talent von Heilig."
L["The remaining 20 points go to Retribution: cheaper spells and more melee crit while questing, ending in Seal of Command."] = "Die übrigen 20 Punkte gehen in Vergeltung: günstigere Zauber und mehr Nahkampf-Crit beim Questen, am Ende Siegel des Befehls."
L["Open with Redoubt: blocking pays off at once, and Shield Specialization needs all five ranks."] = "Beginne mit Verschanzen: Blocken zahlt sich sofort aus, und die Schild-Spezialisierung braucht alle fünf Ränge."
L["Precision and Anticipation help you land hits and dodge them while questing with a shield."] = "Präzision und Vorahnung helfen dir, Treffer zu landen und ihnen auszuweichen, wenn du mit Schild questest."
L["Improved Seal of Fury and Improved Righteous Fury begin the mana and mitigation cycle Forever tanking is built on."] = "Verbessertes Siegel des Furors und Verbesserter Zorn der Gerechtigkeit beginnen den Mana- und Schadensminderungs-Zyklus, auf dem das Tanken in Forever aufbaut."
L["Around 20 points in, you match the usual dungeon-tank setup: Shield Specialization, Sacred Duty and Swift Judgement are complete."] = "Etwa ab 20 Punkten entspricht dein Build dem üblichen Dungeon-Tank-Setup: Schild-Spezialisierung, Heilige Pflicht und Schnelles Richturteil sind abgeschlossen."
L["Templar's Bulwark is an absorb cooldown that scales with your health, and Holy Shield later in the plan requires it."] = "Bollwerk des Templers ist eine Absorptions-Abklingzeit, die mit deiner Gesundheit skaliert, und der Heilige Schild später im Plan setzt sie voraus."
L["Iron Creed adds threat and damage reduction to Holy Strike while Righteous Fury is active."] = "Eiserner Glaube gibt Heiliger Stoß zusätzliche Bedrohung und Schadensminderung, solange Zorn der Gerechtigkeit aktiv ist."
L["Holy Shield is the capstone: more block uptime, with Holy damage each time you block. Ideal for pulling packs."] = "Heiliger Schild ist der Abschluss: mehr Blockzeit, mit Heiligschaden bei jedem Block. Ideal, um Gruppen zu pullen."
L["Leftover points buy armor, a quicker Hammer of Justice, and Holy Strength and seal damage for leveling."] = "Übrige Punkte kaufen Rüstung, einen schnelleren Hammer der Gerechtigkeit sowie Heilige Stärke und Siegelschaden zum Leveln."
L["Benediction lowers the mana cost of Judgement, Holy Strike and seals, so you rest less between fights."] = "Segnung senkt die Manakosten von Richturteil, Heiliger Stoß und Siegeln, sodass du zwischen Kämpfen weniger rastest."
L["Seal of Command is the main two-hander seal for leveling; take it as soon as it opens."] = "Siegel des Befehls ist das wichtigste Zweihand-Siegel zum Leveln; nimm es, sobald es sich öffnet."
L["Sanctified Judgement gives mana back and is the prerequisite arrow for Vengeance."] = "Gesegnetes Richturteil gibt Mana zurück und ist der Voraussetzungspfeil für Rache."
L["Sacred Arbiter strengthens Holy Strike and keeps Judgements rolling, and completes the 20 points row 5 asks for."] = "Heiliger Richter stärkt Heiliger Stoß, hält Richturteile am Laufen und schließt die 20 Punkte ab, die Reihe 5 verlangt."
L["Vengeance, then Two-Handed Weapon Specialization: the crit-driven damage core of the two-hander plan."] = "Rache, dann Zweihandwaffen-Spezialisierung: der Crit-getriebene Schadenskern des Zweihand-Plans."
L["Pursuit of Justice adds run speed. Champion of the Light is left out while the Retribution Aura spell-power bug keeps spell damage low."] = "Streben nach Gerechtigkeit erhöht die Laufgeschwindigkeit. Champion des Lichts bleibt draußen, solange der Fehler bei der Zaubermacht der Aura der Vergeltung den Zauberschaden niedrig hält."
L["Twist of Light makes swapping seals cheaper and adds seal echoes; it is Forever's seal-twisting talent."] = "Wendung des Lichts macht das Wechseln von Siegeln günstiger und fügt Siegel-Echos hinzu; es ist das Siegel-Twisting-Talent von Forever."
L["Spare points go to Divine Strength and Holy's Improved Seals for damage, then Deflection for survival."] = "Übrige Punkte gehen in Göttliche Stärke und Verbesserte Siegel von Heilig für Schaden, dann in Abwehr fürs Überleben."
L["Level as Combat with a sword (Riposte, Blade Flurry, Adrenaline Rush) for the steadiest kills, or Assassination with daggers and poisons (Mutilate). Subtlety's Hemorrhage plan suits stealth openers and is slower solo."] = "Levele als Kampf mit einem Schwert (Riposte, Klingenwirbel, Adrenalinrausch) für beständige Kills oder als Meucheln mit Dolchen und Giften (Verstümmeln). Der Blutsturz-Plan von Täuschung eignet sich für Stealth-Eröffnungen und ist solo langsamer."
L["Malice first: crit for every attack and poison, and it opens Lethality."] = "Zuerst Tücke: Krit für jeden Angriff und Gift, und es öffnet Tödlichkeit."
L["Ruthlessness gives finishers a chance at a free combo point; Murder adds damage against humanoids and giants."] = "Skrupellosigkeit gibt Finishern die Chance auf einen freien Kombopunkt; Mord fügt Schaden gegen Humanoide und Riesen hinzu."
L["Relentless Strikes refunds energy from finishers, so fights flow without waiting."] = "Unerbittliche Stöße erstatten Energie von Finishern zurück, sodass Kämpfe ohne Warten fließen."
L["Improved Poisons puts poisons on more often and makes charges last; take them as soon as you train poisons."] = "Verbesserte Gifte trägt Gifte häufiger auf und lässt Ladungen länger halten; nimm sie sobald du Gifte trainierst."
L["Mutilate is Forever's dual-wield dagger strike: two combo points a use, and more damage on poisoned targets."] = "Verstümmeln ist Forevers Zweiwaffen-Dolchschlag: zwei Kombopunkte pro Einsatz und mehr Schaden auf vergiftete Ziele."
L["Seal Fate turns crits into extra combo points; with Malice and Lethality it is the core of the build."] = "Schicksal besiegeln wandelt Krits in extra Kombopunkte um; mit Tücke und Tödlichkeit ist es der Kern des Builds."
L["Venom is the capstone: a finisher that strengthens your poisons for a while."] = "Toxin ist der Höhepunkt: ein Finisher, der deine Gifte für eine Weile stärkt."
L["The last 20 points go to Combat: cheaper Sinister Strikes, a stronger Eviscerate, more hit and parry, Riposte and a stronger off-hand."] = "Die letzten 20 Punkte gehen in Kampf: günstigere Finstere Stöße, ein stärkeres Ausweiden, mehr Trefferwertung und Parieren, Riposte und eine stärkere Nebenhand."
L["Improved Sinister Strike first: cheaper Sinister Strikes are the biggest early gain."] = "Zuerst Verbesserter finsterer Stoß: günstigere Finstere Stöße sind der größte frühe Gewinn."
L["Precision helps you hit more often; it also opens Dual Wield Specialization."] = "Präzision hilft dir, öfter zu treffen; es öffnet auch Beidhändigkeits-Spezialisierung."
L["Riposte follows each parry with a heavy strike that also disarms."] = "Riposte folgt auf jedes Parieren mit einem schweren Schlag, der auch entwaffnet."
L["Blade Flurry is faster attacks and cleave on demand; Hack and Slash then adds extra attacks with swords and axes."] = "Klingenwirbel sind schnellere Angriffe und Hieb auf Abruf; Niedermetzeln fügt dann extra Angriffe mit Schwertern und Äxten hinzu."
L["Adrenaline Rush is the capstone: double energy for 15 seconds, enough for a second mob."] = "Adrenalinrausch ist der Höhepunkt: doppelte Energie für 15 Sekunden, genug für einen zweiten Gegner."
L["The remaining points go to Assassination for crit, free combo points, energy refunds and Lethality."] = "Die verbleibenden Punkte gehen in Täuschung für Krit, kostenlose Kombopunkte, Energie-Rückerstattungen und Tödlichkeit."
L["Opportunity adds damage to Backstab, Ambush and Garrote, your stealth openers."] = "Günstige Gelegenheit fügt Schaden zu Meucheln, Hinterhalt und Erdrosseln hinzu, deinen Stealth-Eröffnungen."
L["Improved Ambush and Initiative make the opener the fight: a likely crit and extra combo points."] = "Verbesserter Hinterhalt und Initiative machen den Opener zum Kampf: ein wahrscheinlicher Krit und extra Kombopunkte."
L["Serrated Blades ignores armor and is the way into Hemorrhage."] = "Gezahnte Klingen ignoriert Rüstung und ist der Weg zu Blutsturz."
L["Hemorrhage is your main builder from here, with any weapon, and it adds to Rupture damage."] = "Blutsturz ist ab hier dein Haupt-Builder mit jeder Waffe und fügt Blutung-Schaden hinzu."
L["Quietus adds damage to Hemorrhage and Ghostly Strike on a low-health target, finishing mobs sooner."] = "Exitus erhöht den Schaden von Blutsturz und Geisterhaftem Stoß gegen ein Ziel mit geringer Gesundheit und beendet Gegner schneller."
L["Thousand Cuts is the capstone: Rupture ticks make your next Hemorrhage cheaper."] = "Tausend Schnitte ist der Höhepunkt: Blutung-Ticks machen deinen nächsten Blutsturz billiger."
L["Level as Arms with a two-hander (Mortal Strike, Sweeping Strikes) or Fury (Enrage, Death Wish, then Flurry and Bloodthirst with two weapons). Protection is slower alone but ready to tank any dungeon on the way."] = "Levele als Waffen mit einer Zweihandwaffe (Tödlicher Stoß, Weitreichende Stöße) oder als Furor (Wutanfall, Todeswunsch, dann Schlaghagel und Blutdurst mit zwei Waffen). Schutz ist allein langsamer, aber bereit, jeden Dungeon auf dem Weg zu tanken."
L["Improved Heroic Strike first: Heroic Strike is your main rage dump, and a cheaper one means more of them."] = "Zuerst Verbesserter heldenhafter Stoß: Heldenhafter Stoß ist dein Haupt-Wutablasser, und ein günstigerer bedeutet mehr davon."
L["Improved Tactical Mastery keeps rage when you swap stances, so Charge, Overpower and Battle Stance openers cost you nothing."] = "Verbesserter Taktiker behält Wut beim Haltungswechsel, sodass Sturmangriff, Überwältigen und Kampfhaltungs-Eröffner nichts kosten."
L["Anger Management is a steady rage trickle in every fight; on Forever it also slows rage loss between pulls."] = "Aggressionskontrolle ist ein stetiger Wutzufluss in jedem Kampf; auf Forever verlangsamt es auch den Wutverlust zwischen den Kämpfen."
L["Improved Rend and Deep Wounds turn your crits into bleeds; Deep Wounds also opens Impale."] = "Verbessertes Verwunden und Tiefe Wunden verwandeln deine Krits in Blutungen; Tiefe Wunden öffnet auch Durchbohren."
L["Sweeping Strikes makes two-mob pulls quick; Weaponmaster then adds crit, armor penetration or extra attacks for your weapon type."] = "Weitreichende Stöße macht Pulls mit zwei Gegnern schnell; Waffenmeister fügt dann Krit, Rüstungsdurchdringung oder Extra-Angriffe für deinen Waffentyp hinzu."
L["Improved Slam stops Slam from resetting your swing: a free hit between big two-hander swings."] = "Verbessertes Zerschmettern verhindert, dass Zerschmettern deinen Schwung zurücksetzt: ein freier Treffer zwischen großen Zweihandwaffenschwüngen."
L["Mortal Strike is the capstone and your hardest-hitting strike for the rest of the climb."] = "Tödlicher Stoß ist der Höhepunkt und dein härtester Schlag für den Rest des Aufstiegs."
L["The last 20 points go to Fury: Cruelty and Unbridled Wrath give more crit and more rage."] = "Die letzten 20 Punkte gehen in Furor: Grausamkeit und Entfesselter Zorn geben mehr Krit und mehr Wut."
L["Enrage finishes the plan: a damage boost that is often up while you take hits."] = "Wutanfall beendet den Plan: ein Schadensboost, der oft aktiv ist, während du Treffer einsteckst."
L["Cruelty first: more crit for every build, and the way into the Fury tree."] = "Zuerst Grausamkeit: mehr Krit für jeden Build, und der Weg in den Furor-Baum."
L["Unbridled Wrath means more rage from every swing, which matters most with two fast weapons."] = "Entfesselter Zorn bedeutet mehr Wut von jedem Schwung, was am meisten mit zwei schnellen Waffen zählt."
L["Piercing Howl stops runners and lets you walk away from a bad pull."] = "Durchdringendes Heulen stoppt Fliehende und lässt dich aus einem schlechten Pull herausgehen."
L["Enrage raises your physical damage after you are hit, so it is often up while you take hits."] = "Wutanfall erhöht deinen physischen Schaden, nachdem du getroffen wirst, sodass er oft aktiv ist, während du Treffer einsteckst."
L["Death Wish is a big cooldown for elites and a fear breaker; it also opens Flurry."] = "Todeswunsch ist ein großer Cooldown für Elites und bricht Angst; er öffnet auch Schlaghagel."
L["Dual Wield Specialization: more off-hand damage and rage now that you carry two weapons."] = "Beidhändigkeits-Spezialisierung: mehr Nebenhandschaden und Wut, da du jetzt zwei Waffen trägst."
L["Bloodthirst is the capstone: a strong instant attack and a little run speed between mobs."] = "Blutdurst ist der Höhepunkt: ein starker Sofortangriff und etwas Laufgeschwindigkeit zwischen Gegnern."
L["Gore Drinker turns your rage cooldowns into self-healing, so you rest less."] = "Blutgier verwandelt deine Wut-Abklingzeiten in Selbstheilung, sodass du weniger rastest."
L["Spare points go to Arms for cheaper Heroic Strikes, stance-swap rage, Anger Management and Deep Wounds."] = "Übrige Punkte gehen in Waffen für günstigere Heldenhafte Stöße, Haltungswechsel-Wut, Aggressionskontrolle und Tiefe Wunden."
L["Shield Specialization: more blocks, and on Forever each block also gives rage."] = "Schildspezialisierung: mehr Blocks, und auf Forever gibt jeder Block auch Wut."
L["Improved Revenge makes Revenge, which you can use after each block, a real damage hit."] = "Verbesserte Rache macht Rache, die du nach jedem Block einsetzen kannst, zu einem echten Schadens-Treffer."
L["Last Stand is your emergency cooldown when a pull goes wrong."] = "Letztes Gefecht ist dein Notfall-Cooldown, wenn ein Pull schiefläuft."
L["Vanguard lets you Charge from Defensive Stance: no stance dance to open a pull."] = "Frontkämpfer lässt dich aus der Verteidigungshaltung Sturmangriff einsetzen: kein Haltungstanz, um einen Pull zu eröffnen."
L["Concussion Blow is a stun on demand, for an interrupt or to reach a runner."] = "Erschütternder Schlag ist eine Betäubung auf Abruf, für eine Unterbrechung oder um einen Fliehenden zu erreichen."
L["Bastion adds damage to everything you do with a shield on; it is what makes Protection level well."] = "Bastion fügt allem Schaden hinzu, was du mit einem Schild machst; es ist das, was Schutz gut leveln lässt."
L["Shield Slam is the capstone: a big hit that grows with your block value, and high threat for dungeons."] = "Schildschlag ist der Höhepunkt: ein großer Treffer, der mit deinem Blockwert wächst, und hohe Bedrohung für Dungeons."
L["Defiance, Improved Thunder Clap and Improved Shield Wall round out the tank kit for dungeons."] = "Trotz, Verbesserter Donnerknall und Verbesserter Schildwall vervollständigen das Tankkit für Dungeons."
L["The last 10 points go to Arms: cheaper Heroic Strikes and Improved Tactical Mastery for swaps to Battle Stance."] = "Die letzten 10 Punkte gehen in Waffen: günstigere Heldenhafte Stöße und Verbesserter Taktiker für Wechsel zur Kampfhaltung."
L["Level as Frost (the safest: slows, freezes and Ice Barrier) or Fire (more damage, with Pyroblast openers and Blast Wave). Arcane builds around Arcane Blast and Arcane Power and wants more mana between pulls."] = "Levele als Frost (das sicherste: Verlangsamungen, Einfrierungen und Eisbarriere) oder als Feuer (mehr Schaden, mit Pyroschlag-Eröffnern und Druckwelle). Arkan baut um Arkanschlag und Arkane Macht und braucht mehr Mana zwischen den Kämpfen."
L["Improved Channeling first: Arcane Missiles, and later Arcane Blast, keep going when a mob hits you."] = "Zuerst Verbesserte Kanalisierung: Arkane Geschosse und später Arkanschlag laufen weiter, wenn ein Gegner dich trifft."
L["Arcane Concentration gives free casts now and then, and opens Arcane Meditation."] = "Arkane Konzentration gibt ab und zu kostenlose Zauber und öffnet Arkane Meditation."
L["Arcane Blast is Forever's Arcane builder: each cast adds spell power for the next."] = "Arkanschlag ist Forevers Arkan-Builder: jeder Zauber erhöht die Zaubermacht für den nächsten."
L["Missile Barrage: Arcane Blast, Arcane Wrath, Fireball and Frostbolt can make your next Arcane Missiles faster and cheaper."] = "Geschosssalve: Arkanschlag, Arkaner Zorn, Feuerball und Frostblitz können deine nächsten Arkanen Geschosse schneller und günstiger machen."
L["Arcane Meditation keeps mana coming back while you cast, so you drink less."] = "Arkane Meditation lässt Mana zurückkommen während du zauberst, sodass du weniger trinkst."
L["Arcane Wrath, opened by Arcane Blast, is a nuke that grows with your maximum mana. Its point does not count toward the Arcane tiers, so the plan spends 32 points in Arcane."] = "Arkaner Zorn, geöffnet durch Arkanschlag, ist ein Nuke, der mit deinem maximalen Mana wächst. Sein Punkt zählt nicht für die Arkan-Tiers, daher gibt der Plan 32 Punkte in Arkan aus."
L["Presence of Mind makes one spell instant: an opener, or a finisher on a runner."] = "Geistesgegenwart macht einen Zauber sofort: eine Eröffnung oder ein Abschluss bei einem Fliehenden."
L["Arcane Power is the capstone: more damage for more mana, best with Presence of Mind on a tough target."] = "Arkane Macht ist der Höhepunkt: mehr Schaden für mehr Mana, am besten mit Geistesgegenwart gegen ein hartes Ziel."
L["The remaining 19 points go to Frost for a quicker Frostbolt, a shorter Frost Nova cooldown, longer slows and Ice Block."] = "Die verbleibenden 19 Punkte gehen in Frost für einen schnelleren Frostblitz, eine kürzere Frostnova-Abklingzeit, längere Verlangsamungen und Eisblock."
L["Improved Fireball first: a faster Fireball is more damage every fight."] = "Zuerst Verbesserter Feuerball: ein schnellerer Feuerball bedeutet mehr Schaden in jedem Kampf."
L["Ignite adds burn damage to every Fire crit."] = "Entzünden fügt jedem Feuer-Krit Brandschaden hinzu."
L["Pyroblast is a big opener from range; cast it first, then Fireball."] = "Pyroschlag ist ein großer Fernkampf-Eröffner; zaubere ihn zuerst, dann Feuerball."
L["Master of Elements gives mana back on crits, so you rest less."] = "Meister der Elemente gibt Mana bei Krits zurück, sodass du weniger rastest."
L["Critical Mass and Blast Wave: more crits, and an area attack and daze for when two mobs reach you."] = "Kritische Masse und Druckwelle: mehr Krits, und ein Flächenangriff mit Betäubung, wenn zwei Gegner dich erreichen."
L["Fire Power raises your Fire damage for each of your Fire effects on the target: Ignite, Pyroblast's burn and the like."] = "Feuermacht erhöht deinen Feuerschaden für jeden deiner Feuereffekte auf dem Ziel: Entzünden, der Brand von Pyroschlag und Ähnliches."
L["Combustion is the capstone: a crit cooldown for elites and big pulls."] = "Verbrennung ist der Höhepunkt: ein Krit-Cooldown für Elites und große Pulls."
L["The last 20 points go to Arcane: a stronger wand for finishing mobs, then Arcane Concentration's free casts and Arcane Meditation's regen while casting."] = "Die letzten 20 Punkte gehen in Arkan: ein stärkerer Zauberstab zum Töten von Gegnern, dann kostenlose Zauber durch Arkane Konzentration und Regeneration beim Zaubern durch Arkane Meditation."
L["Improved Frostbolt first: a faster Frostbolt is your main gain for the early levels."] = "Zuerst Verbesserter Frostblitz: ein schnellerer Frostblitz ist dein Hauptgewinn für die frühen Level."
L["Ice Shards makes Frost crits hit much harder."] = "Eissplitter lässt Frost-Krits viel härter treffen."
L["Improved Frost Nova and Ice Block are your escapes: freeze, step back, keep casting."] = "Verbesserte Frostnova und Eisblock sind deine Fluchtwege: Einfrieren, zurücktreten, weiter zaubern."
L["Shatter adds a large crit chance against frozen targets: Frost Nova, then Frostbolt or Ice Lance."] = "Zertrümmern fügt eine große Krit-Chance gegen gefrorene Ziele hinzu: Frostnova, dann Frostblitz oder Eislanze."
L["Ice Barrier is the capstone: an absorb shield that also stops pushback while you cast."] = "Eisbarriere ist der Höhepunkt: ein Absorb-Schild, das auch Rückschlag während des Zauberns stoppt."
L["Level as Affliction (instant Corruption, Siphon Life, drains) or Demonology (a tougher Voidwalker, Soul Link) for the fewest deaths. Destruction hits hardest with Conflagrate and Incinerate but needs more rest."] = "Levele als Gebrechen (sofortige Verderbnis, Lebensentzug, Entzüge) oder als Dämonologie (ein stärkerer Leerwandler, Seelenverbindung) für die wenigsten Tode. Zerstörung trifft am härtesten mit Feuersbrunst und Verbrennen, braucht aber mehr Rast."
L["Improved Corruption makes Corruption instant: the core of Affliction leveling."] = "Verbesserte Verderbnis macht Verderbnis sofort: der Kern des Gebrechen-Levelns."
L["Improved Drains and Soul Harvest make Drain Life a heal and Drain Soul a mana return on kills."] = "Verbessertes Entziehen und Seelenernte machen Blutsauger zu einer Heilung und Seelendieb zu einer Mana-Rückgabe bei Kills."
L["Nightfall gives an instant Shadow Bolt now and then while your damage over time ticks."] = "Einbruch der Nacht gibt ab und zu einen sofortigen Schattenblitz, während deine Schadenseffekte ticken."
L["Siphon Life adds another self-heal over time to the rotation."] = "Lebensentzug fügt der Rotation eine weitere Selbstheilung über Zeit hinzu."
L["Shadow Mastery adds damage to every Shadow spell."] = "Schattenbeherrschung fügt jedem Schattenzauber Schaden hinzu."
L["Wrack is the capstone: a strong channel that raises the damage the target takes from your other Shadow damage-over-time effects by 10%."] = "Zermürben ist der Höhepunkt: eine starke Kanalisierung, die den Schaden, den das Ziel durch deine anderen Schattenschaden-über-Zeit-Effekte erleidet, um 10 Prozent erhöht."
L["The last 20 points go to Demonology: more Stamina, a tougher Voidwalker, quicker summons and Demonic Sacrifice."] = "Die letzten 20 Punkte gehen in Dämonologie: mehr Ausdauer, ein stärkerer Leerwandler, schnellere Beschwörungen und Dämonische Opferung."
L["Demonic Embrace first: more Stamina means more Life Taps and fewer deaths."] = "Zuerst Dämonische Umarmung: mehr Ausdauer bedeutet mehr Lebenszapfungen und weniger Tode."
L["Improved Voidwalker makes your tank pet hold mobs better and shield you."] = "Verbesserter Leerwandler lässt deinen Tank-Begleiter Gegner besser halten und dich schützen."
L["Soul Link shares your damage with your pet: with a Voidwalker you rarely die."] = "Seelenverbindung teilt deinen Schaden mit deinem Begleiter: mit einem Leerwandler stirbst du selten."
L["Demonic Pact is the capstone: you keep Demonic Sacrifice's effect when you summon another demon."] = "Dämonischer Pakt ist der Höhepunkt: du behältst den Effekt von Dämonischer Opferung, wenn du einen anderen Dämon beschwörst."
L["The rest goes to Affliction: an instant Corruption, stronger drains and Life Tap, and Nightfall's free Shadow Bolts."] = "Der Rest geht in Gebrechen: eine sofortige Verderbnis, stärkere Entzüge und Aderlass, und die kostenlosen Schattenblitze von Einbruch der Nacht."
L["Bane first: faster Shadow Bolts and Immolates."] = "Zuerst Dunkle Macht: schnellere Schattenblitze und Feuerbrände."
L["Ruin makes Destruction crits hit much harder."] = "Verderben lässt Zerstörungs-Krits viel härter treffen."
L["Conflagrate turns your Immolate into burst damage; open with Immolate, then Conflagrate."] = "Feuersbrunst verwandelt deinen Feuerbrand in Burst-Schaden; eröffne mit Feuerbrand, dann Feuersbrunst."
L["Incinerate is the capstone: a strong Fire nuke, best on an Immolated target."] = "Verbrennen ist der Höhepunkt: ein starker Feuer-Nuke, am besten gegen ein verbranntes Ziel."
L["Level as Feral Combat: Cat Form for quick kills, Bear Form for tough pulls, and no drinking. Balance kills from range with roots and Starfire; Restoration heals any dungeon and quests slowly with Wrath."] = "Levele als Wilder Kampf: Katzengestalt für schnelle Kills, Bärengestalt für harte Pulls und kein Trinken. Gleichgewicht tötet aus der Ferne mit Wurzeln und Sternenfeuer; Wiederherstellung heilt jeden Dungeon und quested langsam mit Zorn."
L["Improved Wrath first: a faster, cheaper Wrath is most of your early damage."] = "Zuerst Verbesserter Zorn: ein schnellerer, günstigerer Zorn ist der Großteil deines frühen Schadens."
L["Moonglow and Nature's Majesty: cheaper spells and more crit."] = "Mondschein und Erhabenheit der Natur: günstigere Zauber und mehr Krit."
L["Improved Entangling Roots holds a mob in place while you nuke it from range."] = "Verbesserte Wucherwurzeln hält einen Gegner fest, während du ihn aus der Ferne niederstreckst."
L["Nature's Grace speeds up your next spell after a crit."] = "Anmut der Natur beschleunigt deinen nächsten Zauber nach einem Krit."
L["Moonkin Form is the capstone: armor and more free casts while you nuke."] = "Moonkingestalt ist der Höhepunkt: Rüstung und mehr kostenlose Zauber, während du nukest."
L["The last 20 points go to Restoration: fewer interrupted casts, Naturalist's damage, regen while casting and stronger heals."] = "Die letzten 20 Punkte gehen in Wiederherstellung: weniger unterbrochene Zauber, der Schaden von Naturalist, Regeneration beim Zaubern und stärkere Heilungen."
L["Ferocity first: cheaper Claw, Rake and Maul in both forms."] = "Zuerst Wildheit: günstigere Klaue, Kratzen und Totschlagen in beiden Gestalten."
L["Savage Fury and Sharpened Claws add damage and crit in Cat and Bear Form."] = "Ungezähmte Wut und Geschärfte Klauen fügen Schaden und Krit in Katzen- und Bärengestalt hinzu."
L["Predatory Strikes adds attack power in forms; it scales with your level, not your gear."] = "Raubtierschläge fügen Angriffsmacht in Gestalten hinzu; sie skalieren mit deiner Stufe, nicht mit deiner Ausrüstung."
L["Leader of the Pack adds crit for you and your group."] = "Rudelführer fügt Krit für dich und deine Gruppe hinzu."
L["Berserk is the capstone: a cooldown that makes Primal Bite hit several targets."] = "Berserker ist der Höhepunkt: ein Cooldown, der den Urtümlichen Biss mehrere Ziele treffen lässt."
L["The last 20 points go to Restoration: rage when you shift, Naturalist's damage, cheaper shifting and regen while casting."] = "Die letzten 20 Punkte gehen in Wiederherstellung: Wut beim Gestaltwandel, der Schaden von Naturalist, günstigerer Gestaltwandel und Regeneration beim Zaubern."
L["Nature's Focus first: your casts go through while a mob hits you."] = "Zuerst Naturfokus: deine Zauber gehen durch, während ein Gegner dich trifft."
L["Reflection keeps mana coming back while casting, so you rest less."] = "Reflexion lässt Mana beim Zaubern zurückkommen, sodass du weniger rastest."
L["Swiftmend uses up a Rejuvenation or Regrowth for a big instant heal."] = "Rasche Heilung verbraucht eine Verjüngung oder ein Nachwachsen für eine große Sofort-Heilung."
L["Wild Growth is the capstone: a heal over time on your whole group."] = "Wildwuchs ist der Höhepunkt: eine Heilung über Zeit für deine gesamte Gruppe."
L["The last 20 points go to Balance so you can still kill quest mobs: a faster, cheaper Wrath, roots and more crit."] = "Die letzten 20 Punkte gehen in Gleichgewicht, damit du Quest-Gegner noch töten kannst: ein schnellerer, günstigerer Zorn, Wurzeln und mehr Krit."
L["Level as Enhancement (Flurry, Stormstrike, Maelstrom Weapon) for steady melee with few rests, or Elemental (Lightning Overload, Lava Burst) to kill from range. Restoration heals dungeons well and levels slowly alone."] = "Levele als Verstärkung (Schlaghagel, Sturmschlag, Waffe des Mahlstroms) für stetigen Nahkampf mit wenig Rast oder als Elementar (Blitzschlag-Überladung, Lavaeruption) für Fernkampf-Kills. Wiederherstellung heilt Dungeons gut und levelt allein langsam."
L["Concussion first: more damage from Lightning Bolt and Earth Shock, your two main spells."] = "Zuerst Erschütterung: mehr Schaden von Blitzschlag und Erdschock, deinen zwei Hauptzaubern."
L["Elemental Focus makes some casts free, which is the main mana saver for the early levels."] = "Elementarfokus macht einige Zauber kostenlos, was der Haupt-Manasparer für die frühen Stufen ist."
L["Lava Burst is a big Fire nuke, best after Flame Shock; Call of Flame makes it stronger."] = "Lavaeruption ist ein großer Feuer-Nuke, am besten nach Flammenschock; Ruf der Flamme macht ihn stärker."
L["Lightning Overload sometimes casts a second, smaller Lightning Bolt for free."] = "Blitzschlag-Überladung zaubert manchmal einen zweiten, kleineren Blitzschlag kostenlos."
L["Elemental Mastery is the capstone: for a while, quicker Lightning Bolts and Lava Bursts and no cooldown on Chain Lightning."] = "Elementarbeherrschung ist der Höhepunkt: für eine Weile schnellere Blitzschläge und Lavaeruptionen und kein Cooldown auf Kettenblitzschlag."
L["The last 20 points go to Enhancement: more Intellect, more crit, a stronger Lightning Shield and cheaper Shocks."] = "Die letzten 20 Punkte gehen in Verstärkung: mehr Intellekt, mehr Krit, ein stärkerer Blitzschlagschild und günstigere Schocks."
L["Thundering Strikes first: crit for spells and attacks, and the way into the tree."] = "Zuerst Donnernde Stöße: Krit für Zauber und Angriffe und der Weg in den Baum."
L["Mental Dexterity turns your Intellect into attack power, so mana gear helps your melee too; it also opens Flurry."] = "Geistige Gewandtheit verwandelt deinen Intellekt in Angriffsmacht, sodass Mana-Ausrüstung auch deinem Nahkampf hilft; es öffnet auch Schlaghagel."
L["Flurry speeds up your swings after a crit and is the core of Enhancement's damage."] = "Schlaghagel beschleunigt deine Schwünge nach einem Krit und ist der Kern des Verstärkungs-Schadens."
L["Stormstrike is an instant strike that raises the damage your next spells do."] = "Sturmschlag ist ein sofortiger Angriff, der den Schaden deiner nächsten Zauber erhöht."
L["Maelstrom Weapon makes your next Lightning Bolt faster and cheaper as you hit."] = "Waffe des Mahlstroms macht deinen nächsten Blitzschlag schneller und günstiger, während du triffst."
L["Rage of the Farseer is the capstone: a big attack-speed cooldown for elites and pulls."] = "Zorn des Scharfsehers ist der Höhepunkt: ein großer Angriffsgeschwindigkeits-Cooldown für Elites und Pulls."
L["The last 20 points go to Elemental for stronger Shocks, cheaper casts and more crit from spells."] = "Die letzten 20 Punkte gehen in Elementar für stärkere Schocks, günstigere Zauber und mehr Krit von Zaubern."
L["Tidal Focus first: cheaper heals, and more hit for your Lightning Bolts while you quest."] = "Zuerst Gezeitenfokus: günstigere Heilungen und mehr Trefferwertung für deine Blitzschläge, während du questest."
L["Totemic Focus: cheaper totems, which you drop on every pull while leveling."] = "Totemfokus: günstigere Totems, die du bei jedem Pull während des Levelns aufstellst."
L["Mindfulness keeps half your mana regeneration going while casting."] = "Achtsamkeit hält die Hälfte deiner Mana-Regeneration während des Zauberns aufrecht."
L["Nature's Swiftness makes one heal instant: your emergency button."] = "Schnelligkeit der Natur macht eine Heilung sofort: dein Notfallknopf."
L["Riptide is the capstone: a quick heal with a heal over time for dungeons."] = "Springflut ist der Höhepunkt: eine schnelle Heilung mit einer Heilung über Zeit für Dungeons."
L["The last 20 points go to Elemental, so your Lightning Bolts and Shocks still kill while you quest."] = "Die letzten 20 Punkte gehen in Elementar, damit deine Blitzschläge und Schocks beim Questen noch töten."
L["Feral Combat"] = "Wilder Kampf"
L["Restoration"] = "Wiederherstellung"
L["Level as Beast Mastery: your pet tanks and does much of the damage, so you rarely stop. Marksmanship hits harder from range with Careful Aim and Sniper Shot; Survival fights in melee with Predator's Edge and Lacerating Strikes."] = "Levele als Tierherrschaft: dein Begleiter tankt und macht viel Schaden, sodass du selten stoppst. Treffsicherheit trifft härter aus der Ferne mit Sorgfältigem Zielen und Heckenschützenschuss; Überleben kämpft im Nahkampf mit Vorteil des Raubtiers und Aufschlitzenden Schlägen."
L["Deadly Aspects first: more from Aspect of the Hawk while your pet holds the mob."] = "Zuerst Tödliche Aspekte: mehr aus dem Aspekt des Falken, während dein Begleiter den Gegner hält."
L["Unleashed Fury adds pet damage, and your pet is most of your damage."] = "Entfesselter Zorn fügt Begleiter-Schaden hinzu, und dein Begleiter ist der Großteil deines Schadens."
L["Intimidation stuns through your pet: a breather when a mob turns on you."] = "Einschüchterung betäubt über deinen Begleiter: eine Atempause wenn ein Gegner sich auf dich stürzt."
L["Bestial Wrath is the capstone: your pet's big damage cooldown."] = "Zorn des Wildtiers ist der Höhepunkt: der große Schaden-Cooldown deines Begleiters."
L["The last 20 points go to Marksmanship: more crit, attack power from Intellect, a shorter Rapid Fire and harder ranged crits."] = "Die letzten 20 Punkte gehen in Treffsicherheit: mehr Krit, Angriffsmacht aus Intellekt, ein kürzeres Schnellfeuer und härtere Fernkampf-Krits."
L["Lethal Attacks first: crit for every shot."] = "Zuerst Tödliche Angriffe: Krit für jeden Schuss."
L["Careful Aim adds attack power from your Intellect."] = "Sorgfältiges Zielen fügt Angriffsmacht aus deinem Intellekt hinzu."
L["Mortal Shots makes your ranged crits hit much harder."] = "Todbringende Schüsse lässt deine Fernkampf-Krits viel härter treffen."
L["Sniper Shot is the capstone: a long-range opener that hits hard."] = "Heckenschützenschuss ist der Höhepunkt: ein Langstrecken-Eröffner, der hart trifft."
L["The last 20 points go to Beast Mastery: a stronger Aspect of the Hawk and a tougher, harder-hitting pet."] = "Die letzten 20 Punkte gehen in Tierherrschaft: ein stärkerer Aspekt des Falken und ein zäherer, härter treffender Begleiter."
L["Improved Tracking first: keep tracking on for its bonus against the mobs you quest on."] = "Zuerst Verbessertes Fährtenlesen: Aufspüren für den Bonus gegen die Gegner eingeschaltet halten, auf die du questest."
L["Deterrence is a dodge and parry cooldown for melee fights that go wrong."] = "Abschreckung ist ein Ausweich- und Parieren-Cooldown für Nahkämpfe, die schiefgehen."
L["Lightning Reflexes adds Agility: more attack power, crit and dodge."] = "Blitzartige Reflexe fügen Beweglichkeit hinzu: mehr Angriffsmacht, Krit und Ausweichen."
L["Lacerating Strikes is the capstone: Mongoose Bite also makes the target bleed."] = "Aufschlitzende Schläge sind der Höhepunkt: Mungobiss lässt das Ziel auch bluten."
L["Level as Shadow (Spirit Tap, Mind Flay, Shadowform) for the fastest kills and least drinking. Discipline levels with Smite and Penance behind a strong shield; Holy is the dungeon healer and slower alone."] = "Levele als Schatten (Willensentzug, Gedankenschinden, Schattengestalt) für die schnellsten Kills und wenig Trinken. Disziplin levelt mit Göttlicher Pein und Sühne hinter einem starken Schild; Heilig ist der Dungeon-Heiler und allein langsamer."
L["Power in Light first: more Smite damage, your main attack as Discipline, on targets with your Holy Fire or Shadow Word: Pain."] = "Zuerst Macht im Licht: mehr Schaden von Göttlicher Pein, dein Hauptangriff als Disziplin, gegen Ziele mit deinem Heiligen Feuer oder Schattenwort: Schmerz."
L["Improved Power Word: Shield: a bigger shield is fewer interrupted casts and less healing."] = "Verbessertes Machtwort: Schild: ein größeres Schild bedeutet weniger unterbrochene Zauber und weniger Heilung."
L["Penance is a channelled burst of Holy damage or healing: use it on every mob."] = "Sühne ist ein Kanal-Ausbruch von Heiligem Schaden oder Heilung: verwende sie bei jedem Gegner."
L["Power Infusion is the capstone: a damage and healing cooldown for you or an ally."] = "Seele der Macht ist der Höhepunkt: ein Schaden- und Heilungs-Cooldown für dich oder einen Verbündeten."
L["The last 20 points go to Shadow: Spirit Tap's regen after kills, a longer Shadow Word: Pain, more Shadow hit, Mind Flay and a quicker Mind Blast."] = "Die letzten 20 Punkte gehen in Schatten: die Regeneration von Willensentzug nach Kills, ein längeres Schattenwort: Schmerz, mehr Schattentrefferwertung, Gedankenschinden und ein schnellerer Gedankenschlag."
L["Holy Specialization first: more crits on Smite and on your heals."] = "Zuerst Heiligspezialisierung: mehr Krits auf Göttliche Pein und auf deine Heilungen."
L["Divine Fury speeds up Smite, Holy Fire and your big heals."] = "Göttlicher Furor beschleunigt Göttliche Pein, Heiliges Feuer und deine großen Heilungen."
L["Spiritual Guidance adds 25% of your Spirit to your healing but only 8% to your damage: Spirit gear helps your heals most."] = "Geistige Führung gibt 25% deiner Willenskraft als Heilung dazu, aber nur 8% als Schaden: Ausrüstung mit Willenskraft hilft deinen Heilzaubern am meisten."
L["Prayer of Mending is the capstone: a heal that jumps between your group as they take damage."] = "Gebet der Besserung ist der Höhepunkt: eine Heilung, die zwischen deiner Gruppe springt, wenn sie Schaden erleiden."
L["The last 20 points go to Discipline: a stronger wand, a bigger Power Word: Shield, Meditation's regen while casting and more Intellect."] = "Die letzten 20 Punkte gehen in Disziplin: ein stärkerer Zauberstab, ein größeres Machtwort: Schild, die Regeneration von Meditation beim Zaubern und mehr Intellekt."
L["Mental Strength comes last: on Forever its points do not count toward the Discipline tiers."] = "Mentale Stärke kommt zuletzt: auf Forever zählen seine Punkte nicht für die Disziplin-Tiers."
L["Spirit Tap first: after each kill your regen jumps, so you drink far less."] = "Zuerst Willensentzug: nach jedem Kill springt deine Regeneration, sodass du viel weniger trinkst."
L["Mind Flay is your main damage and slow from here; Improved Mind Flay makes it hit harder."] = "Gedankenschinden ist ab hier dein Haupt-Schaden und deine Verlangsamung; Verbessertes Gedankenschinden lässt es härter treffen."
L["Vampiric Embrace heals you from your Shadow damage."] = "Vampirumarmung heilt dich durch deinen Schattenschaden."
L["Shadowform is the capstone: more Shadow damage and less physical damage taken."] = "Schattengestalt ist der Höhepunkt: mehr Schattenschaden und weniger erlittener physischer Schaden."
L["ForeverDB through level 30, Polestar after"] = "ForeverDB bis Stufe 30, danach Polestar"
L["Polestar, with ForeverDB's builds to level 20"] = "Polestar, mit den Builds von ForeverDB bis Stufe 20"
L["Polestar, with ForeverDB's talent data"] = "Polestar, mit den Talentdaten von ForeverDB"
L["ForeverDB"] = "ForeverDB"
L["ForeverDB's leveling builds, adapted to level 30"] = "Die Leveling-Builds von ForeverDB, auf Stufe 30 angepasst"

-- Dungeons/Dungeons.lua
L["Kill %d %s"] = "Töte %d %s"
L["Collect %s"] = "Sammle %s"
L["Collect %d %s"] = "Sammle %d %s"
L["Use %s"] = "Benutze %s"
L["Dungeons in leveling guides"] = "Dungeons in Leveling-Guides"
L["Off: the guide skips this group quest and keeps to the solo route. Until you choose, it asks when it gets there."] = "Aus: Der Guide überspringt diese Gruppenquest und bleibt auf der Solo-Route. Bis du dich entscheidest, fragt er nach, wenn er dort ankommt."
L["Group quests"] = "Gruppenquests"
L["Group quests in leveling guides"] = "Gruppenquests in Leveling-Guides"
L["Tell me when a dungeon opens up"] = "Sag mir, wenn sich ein Dungeon öffnet"
L["When a level-up opens a dungeon's quests to this character, a card on the guide window says so, once per dungeon, with a button that picks up its quests in a new tab."] = "Wenn ein Stufenaufstieg die Quests eines Dungeons für diesen Charakter freischaltet, sagt dir eine Karte am Guide-Fenster das, einmal pro Dungeon, mit einer Schaltfläche, die dessen Quests in einem neuen Tab zusammenstellt."
L["Entrance in Horde territory (outside the Undercity)"] = "Eingang im Horde-Gebiet (außerhalb der Unterstadt)"
L["Entrance in Alliance territory (in Ironforge)"] = "Eingang im Allianz-Gebiet (in Eisenschmiede)"
L["Entrance in Horde territory (in Orgrimmar)"] = "Eingang im Horde-Gebiet (in Orgrimmar)"
L["Entrance in Alliance territory (in Stormwind)"] = "Eingang im Allianz-Gebiet (in Sturmwind)"
L["Speak with %s"] = "Sprich mit %s"
-- L["Dungeons are turned off (Options > Discovery > Lookup)."] = ""

-- Dungeons/Attune.lua
L["Lets Lothos Riftwaker in Blackrock Mountain send you to the Molten Core; without it, walk in through Blackrock Depths."] = "Lässt dich Lothos Riftwaker im Blackrock zum Geschmolzenen Kern schicken; ohne ihn läufst du durch die Blackrocktiefen hinein."
L["Douses the Molten Core's runes; Majordomo Executus comes out only when every rune is doused. Duke Hydraxis hands it out once Hands of the Enemy is done."] = "Löscht die Runen des Geschmolzenen Kerns; Majordomus Executus erscheint erst, wenn jede Rune gelöscht ist. Fürst Hydraxis gibt es aus, sobald „Hände des Feindes“ erledigt ist."
L["Everyone entering Onyxia's Lair carries the Drakefire Amulet."] = "Jeder, der Onyxias Hort betritt, trägt das Drachenfeueramulett."
L["Lets you touch the Orb of Command in Upper Blackrock Spire to reach Blackwing Lair; without it, walk in through the spire."] = "Lässt dich den Orb of Command in der Blackrockspitze berühren, um den Pechschwingenhort zu erreichen; ohne es läufst du durch die Spitze hinein."
L["Everyone entering Naxxramas needs it; which of the three quests you take depends on your standing with the Argent Dawn."] = "Jeder, der Naxxramas betritt, braucht es; welche der drei Quests du nimmst, hängt von deinem Ruf bei der Argentumdämmerung ab."
L["Opens Scholomance's gate; one key opens it for the group."] = "Öffnet das Tor von Scholomance; ein Schlüssel öffnet es für die Gruppe."
L["Opens the Shadowforge gates in Blackrock Depths; one key opens them for the group."] = "Öffnet die Shadowforge-Tore in den Blackrocktiefen; ein Schlüssel öffnet sie für die Gruppe."
L["Opens the cells of Blackrock Depths' prison."] = "Öffnet die Zellen des Gefängnisses der Blackrocktiefen."
L["Opens the Eastwall Gate into Stratholme's Scourge-held districts."] = "Öffnet das Ostwalltor in die von der Geißel gehaltenen Viertel von Stratholme."
L["Opens the inner doors of Dire Maul's North and West wings."] = "Öffnet die inneren Türen des Nord- und Westflügels des Düsterbruchs."
L["Opens Gnomeregan's back door, the Workshop entrance."] = "Öffnet Gnomeregans Hintertür, den Werkstatteingang."
L["Opens the doors of the Armory and the Cathedral."] = "Öffnet die Türen der Waffenkammer und der Kathedrale."
L["Opens the gate of the Horde's way into the City of Dalaran; one key opens it for the group. The Alliance walks in through the sewer pipe in Cantrips & Crows."] = "Öffnet das Tor des Weges der Horde in die Stadt Dalaran; ein Schlüssel öffnet es für die Gruppe. Die Allianz geht durch das Abwasserrohr in Cantrips & Crows hinein."

-- Nav/Handoff.lua
L["Hand guiding to Shortest Path Forever"] = "Führung an Shortest Path Forever abgeben"
L["Shortest Path Forever's arrow, route and journey take you to each goal. Polestar's arrow, route lines, journey steps, travel button, transport alerts, map clicks and /way step aside; the guide window and map pins stay. Off: Polestar guides, and steps aside only while a journey you started in Shortest Path Forever runs."] = "Pfeil, Route und Reise von Shortest Path Forever führen dich zu jedem Ziel. Polestars Pfeil, Routenlinien, Reiseschritte, Reise-Button, Transport-Alarme, Kartenklicks und /way treten zur Seite; das Guide-Fenster und die Kartenmarkierungen bleiben. Aus: Polestar führt und tritt nur zur Seite, solange eine Reise läuft, die du in Shortest Path Forever gestartet hast."

