-- QoL/Buttons.lua
L["Click again for the next name. Shift-drag to move."] = "Klick noch einmal für den nächsten Namen. Halte Umschalt gedrückt und zieh, um es zu verschieben."
L["Press again to delete"] = "Zum Löschen noch einmal drücken"
L["Bag space"] = "Taschenplatz"
L["Press twice to delete it."] = "Zweimal drücken, um ihn zu löschen."
L["a new icon each press"] = "bei jedem Druck ein neues Symbol"
L["Marks it with %s."] = "Markiert es mit %s."
L["Marks it with %s if it has no icon yet: you don't lead the party."] = "Markiert es mit %s, wenn es noch kein Symbol hat: Du führst die Gruppe nicht."
L["Marks nothing: in a raid only the leader and assistants set icons."] = "Markiert nichts: In einem Schlachtzug setzen nur der Anführer und Assistenten Symbole."
L["Target and wave"] = "Anvisieren und winken"
L["You can take the quest this item starts. Click to read it."] = "Du kannst die Quest annehmen, die dieser Gegenstand startet. Klicke, um sie zu lesen."

-- Core/Import.lua
L["Imported"] = "Importiert"
L["This import string is damaged or incomplete. Copy the whole string again."] = "Dieser Importtext ist beschädigt oder unvollständig. Kopiere den ganzen Text noch einmal."
L["This import string needs a newer Polestar."] = "Dieser Importtext braucht ein neueres Polestar."
L["This import string holds no guide."] = "Dieser Importtext enthält keinen Guide."
L["Its guide id %s must start with its author's own id, as in yendi/cozy-sleeping-bag."] = "Seine Guide-ID %s muss mit der eigenen ID des Autors beginnen, wie in yendi/cozy-sleeping-bag."
L["Guides under %s/ come from the community addon %s, which is installed."] = "Guides unter %s/ kommen aus dem Community-Addon %s, das installiert ist."
L["Its guide has %d steps; an import string holds %d at most. A bigger guide comes as a community addon."] = "Sein Guide hat %d Schritte; ein Importtext fasst höchstens %d. Ein größerer Guide kommt als Community-Addon."
L["It leads on to %s, which is neither one of Polestar's guides nor an imported one: import that guide first."] = "Er führt weiter zu %s, das weder ein Guide von Polestar noch ein importierter ist: Importiere zuerst diesen Guide."
L["This import string holds a field Polestar does not read (%s). It may need a newer Polestar."] = "Dieser Importtext enthält ein Feld, das Polestar nicht liest (%s). Vielleicht braucht er ein neueres Polestar."
L["Paste an import string."] = "Füge einen Importtext ein."
L["This import string is too long: Polestar reads up to %d characters."] = "Dieser Importtext ist zu lang: Polestar liest bis zu %d Zeichen."
L["This is not a Polestar import string."] = "Das ist kein Importtext für Polestar."
L["This game client cannot read import strings."] = "Dieser Spielclient kann keine Importtexte lesen."
L["This import string holds a text longer than Polestar reads (%s): %d characters at most."] = "Dieser Importtext enthält einen Text, der länger ist, als Polestar liest (%s): höchstens %d Zeichen."
L["This import string holds too much: Polestar reads up to %d KB of guide data."] = "Dieser Importtext enthält zu viel: Polestar liest bis zu %d KB Guide-Daten."
L["Its guide has %d goals in step %d; an import string holds %d per step at most."] = "Sein Guide hat %d Ziele in Schritt %d; ein Importtext fasst höchstens %d pro Schritt."
L["Its guide has %d candidates in a goal; an import string holds %d per goal at most."] = "Sein Guide hat %d Kandidaten in einem Ziel; ein Importtext fasst höchstens %d pro Ziel."
L["Its guide has more than one direct turn-in for quest %d in step %d."] = "Sein Guide hat mehr als eine direkte Abgabe für Quest %d in Schritt %d."
L["Its guide has a candidate coordinate outside 0-100."] = "Sein Guide hat eine Kandidatenkoordinate außerhalb von 0–100."
L["Its guide has a spot coordinate outside 0-100."] = "Sein Guide hat eine Ortskoordinate außerhalb von 0–100."
L["Its guide has a map frame with missing fields."] = "Sein Guide hat einen Kartenausschnitt mit fehlenden Feldern."
L["Its guide has a degenerate map frame (zero extent)."] = "Sein Guide hat einen entarteten Kartenausschnitt (Ausdehnung null)."
L["Its guide has a map frame with out-of-range coordinates."] = "Sein Guide hat einen Kartenausschnitt mit Koordinaten außerhalb des Bereichs."
L["No imported guides to remove."] = "Keine importierten Guides zum Entfernen."
L["Removed %d imported guide(s)."] = "Importierte Guides entfernt: %d."
L["Usage: /polestar import delete <guide-id>"] = "Verwendung: /polestar import delete <Guide-ID>"
L["Removed imported guide %s."] = "Importierter Guide %s entfernt."
L["No imported guide with id %s."] = "Kein importierter Guide mit der ID %s."
L["Open the Import page; import clear / import delete <id>: remove imports"] = "Die Import-Seite öffnen; import clear / import delete <id>: Importe entfernen"
L["Its guide has %d entries in %s; an import string holds %d there at most."] = "Der Guide hat %d Einträge in %s; ein Importtext fasst dort höchstens %d."

