-- UI/UpdateCard.lua
L["Polestar Client can update it for you: open it, press Update, then restart the game or /reload."] = "Der Polestar Client kann es für dich aktualisieren: Öffne ihn, drück auf „Update“, dann starte das Spiel neu oder gib /reload ein."
L["Update it with the CurseForge app or Polestar Client (or the zip from GitHub), then restart the game or /reload."] = "Aktualisiere es mit der CurseForge-App oder dem Polestar Client (oder dem Zip von GitHub), dann starte das Spiel neu oder gib /reload ein."
L["POLESTAR UPDATE"] = "POLESTAR-UPDATE"
L["Check for a newer Polestar"] = "Nach einem neueren Polestar sehen"
