-- L["Shortest Path Forever's arrow, route and journey take you to each goal. Polestar's arrow, route lines, journey steps, travel button, transport alerts, map clicks and /way step aside; the guide window and map pins stay."] = "Pfeil, Route und Reise von Shortest Path Forever führen dich zu jedem Ziel. Polestars Pfeil, Routenlinien, Reiseschritte, Reise-Button, Transport-Alarme, Kartenklicks und /way treten zur Seite; das Guide-Fenster und die Kartenmarkierungen bleiben."
-- L["Browsing the guide needs a gamepad: turn it on in the game's options and plug one in."] = "Zum Durchgehen des Guides brauchst du ein Gamepad: Aktiviere es in den Spieloptionen und schließ eines an."
-- L["Follow a talent plan for your class and spec (/pole talents). Paladin only for now."] = "Folge einem Talentplan für deine Klasse und Spezialisierung (/pole talents). Vorerst nur Paladin."
-- L["Talent plans cover the Paladin for now. More classes will follow."] = "Talentpläne gibt es vorerst für den Paladin. Weitere Klassen folgen."
-- L["The game's own font (the default), Inter, or EllesmereUI's."] = "Die Schrift des Spiels (Standard), Inter oder die von EllesmereUI."
-- L["Your report"] = "Dein Bericht"
-- L["Select report"] = "Bericht auswählen"
-- L["Copy your report with Ctrl+C (Cmd+C on a Mac), switch to Discord and paste it in the Polestar server. Not in it yet? Get the invite once and open it in your browser."] = "Kopiere deinen Bericht mit Strg+C (Cmd+C auf dem Mac), wechsle zu Discord und füge ihn im Polestar-Server ein. Noch nicht drin? Hol dir einmal die Einladung und öffne sie in deinem Browser."
-- L["Next boat in about %s"] = "Nächstes Boot in etwa %s"
-- L["Next zeppelin in about %s"] = "Nächster Zeppelin in etwa %s"
-- L["Next tram in about %s"] = "Nächste Bahn in etwa %s"
-- L["Next lift in about %s"] = "Nächster Aufzug in etwa %s"
-- L["leaves in about %s"] = "fährt ab in etwa %s"
-- L["Scale of the quest item, Hearthstone and target buttons. Drag one to move them all."] = "Größe von Questgegenstand-, Ruhestein- und Ziel-Button. Zieh einen, um alle zu verschieben."
-- L["Route"] = "Route"
-- L["Open the Import page: guides shared as text"] = "Seite „Import“ öffnen: als Text geteilte Guides"
