-- Theme/Widgets.lua, UI/Options.lua: the options window's rows, dialog and preview
-- L["Reset to default"] = "Auf Standard zurücksetzen"
-- L["Your manual check-offs and skipped steps in %s are cleared. Quests you have done stay done."] = ""
-- L["Your manual check-offs and skipped steps in the current guide are cleared. Quests you have done stay done."] = ""
-- L["The first walk of %s"] = ""
-- L["The step you are on."] = "Der Schritt, bei dem du bist."
-- L["Points the way."] = "Zeigt den Weg."
-- L["The map marks each place."] = "Die Karte markiert jeden Ort."
-- L["Planned in a simulator and played to the end in tests, but nobody has followed them through the live game yet. Skip a wrong step with %s and tell us on Discord."] = "In einem Simulator geplant und in Tests bis zum Ende gespielt, aber noch niemand hat sie im echten Spiel durchgespielt. Überspring einen falschen Schritt mit %s und sag uns auf Discord Bescheid."
-- L["Feedback, bug reports and news"] = "Feedback, Fehlerberichte und Neuigkeiten"
-- L["Guides made by other players for Polestar, not our own routes: each community addon is installed like any other addon. Its guides appear in %s under Community guides, credited to their author, who supports them. More in Options > Community guides."] = "Guides, die andere Spieler für Polestar geschrieben haben, nicht unsere eigenen Routen: Jedes Community-Addon wird wie jedes andere Addon installiert. Seine Guides erscheinen in %s unter Community-Guides, mit dem Namen ihres Autors, der sie betreut. Mehr unter Optionen > Community-Guides."
-- L["How the arrow walks you. You can change it any time in Options."] = "Wie dich der Pfeil führt. Du kannst es jederzeit in den Optionen ändern."
-- L["Sessions stored"] = "Gespeicherte Sitzungen"
-- L["Kept in SavedVariables until imported with the toolchain."] = "Bleiben in den SavedVariables, bis sie mit der Toolchain importiert werden."
-- L["Events this session"] = "Ereignisse in dieser Sitzung"
-- L["Character"] = "Charakter"
-- L["Session"] = "Sitzung"
-- L["Counts and the current session in chat."] = "Zählstände und die aktuelle Sitzung im Chat."
-- L["Opens the gate of the Horde's way into the City of Dalaran; one key opens it for the group. The Alliance is sent in by the Image of Archmage Modera."] = "Öffnet das Tor des Weges der Horde in die Stadt Dalaran; ein Schlüssel öffnet es für die Gruppe. Die Allianz wird vom Abbild der Erzmagierin Modera hineingeschickt."
-- L["Accepted a resurrection."] = "Wiederbelebung angenommen."
-- L["The item the current step uses, or a quest item it collects, glows in your bags (and in Baganator)."] = "Der Gegenstand, den der aktuelle Schritt benutzt, oder ein Questgegenstand, den er sammelt, leuchtet in deinen Taschen (auch in Baganator)."
-- L["Sells Poor-quality items when a merchant opens and prints the total. Never sells anything else."] = "Verkauft Gegenstände schlechter Qualität, wenn ein Händler geöffnet wird, und gibt die Summe aus. Verkauft nie etwas anderes."
-- L["Picks the only option of NPCs without quests. Hold Shift to read it."] = "Wählt die einzige Option von NPCs ohne Quests. Halte Umschalt gedrückt, um es zu lesen."
-- L["Earlier quests of this chain are not listed."] = "Frühere Quests dieser Questreihe werden nicht aufgelistet."
-- L["Small conveniences: travel, invitations, merchants and trackers."] = "Kleine Annehmlichkeiten: Reisen, Einladungen, Händler und Tracker."
-- L["Click to share the quest with your party."] = "Klicken, um die Quest mit deiner Gruppe zu teilen."
-- L["Party members who run Polestar see your counts under their quest goals. Nothing goes to chat."] = "Gruppenmitglieder, die Polestar nutzen, sehen deine Zählstände unter ihren Questzielen. Nichts geht in den Chat."
-- L["Their counts under your quest goals, and who lacks a quest you took."] = "Ihre Zählstände unter deinen Questzielen und wem eine Quest fehlt, die du genommen hast."
-- L["Share %s with %s"] = "%s mit %s teilen"
-- L["Each Polestar member's level, step and what they still need of yours; click a name to point the arrow at them. /polestar party shows or hides it."] = "Stufe und Schritt jedes Polestar-Mitglieds und was es von deinem Schritt noch braucht; ein Klick auf einen Namen richtet den Pfeil auf das Mitglied. /polestar party blendet das Fenster ein oder aus."
-- L["In dungeons"] = "In Dungeons"
-- L["What the window does in dungeons and raids. /polestar or the key binding opens it there until you leave."] = "Was das Fenster in Dungeons und Schlachtzügen tut. /polestar oder die Tastenbelegung öffnet es dort, bis du gehst."
-- L["%s from another version"] = "%s aus einer anderen Version"
-- L["Polestar %s is installed incompletely: %s. Close the game, delete every Polestar folder in Interface/AddOns and unzip the latest Polestar zip there (CurseForge or GitHub Releases, not \"Source code\")."] = "Polestar %s ist unvollständig installiert: %s. Schließe das Spiel, lösche jeden Polestar-Ordner in Interface/AddOns und entpacke dort das neueste Polestar-Zip (CurseForge oder GitHub Releases, nicht „Source code“)."
-- L["About %d bars short of level %s by step %d"] = "Etwa %d Balken zu wenig für Stufe %s bei Schritt %d"
-- L["Objective areas"] = "Zielgebiete"
-- L["Shade the area each group of mobs or objects spreads over on the world map."] = "Schattiert auf der Weltkarte das Gebiet, über das sich jede Gruppe von Mobs oder Objekten verteilt."
-- L["The guide window hides in dungeons and battlegrounds. Type /polestar to show it here, or change it in Options > Guide > Window."] = "Das Guide-Fenster blendet sich in Dungeons und Schlachtfeldern aus. Mit /polestar zeigst du es hier an, oder ändere es unter Optionen > Guide > Fenster."
-- L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. /polestar or the key binding opens it there until you leave."] = "Was das Fenster, seine Schaltflächen und Hinweise in Dungeons, Schlachtzügen, Schlachtfeldern und Arenen tun. /polestar oder die Tastenbelegung öffnet es dort, bis du den Ort verlässt."
-- L["Also a quest ready to hand in whose NPC stands right here, when the guide hands it in later."] = "Auch eine abgabebereite Quest, deren NPC gleich hier steht, wenn der Guide sie erst später abgibt."
-- L["The target button and the step key put a raid icon on the mob and the NPC they target; out of combat, a press that finds neither clears your target. Your party sees the icons; in a raid only the leader and assistants can set them."] = "Der Zielknopf und die Schritttaste setzen eine Zielmarkierung auf den Mob und den NPC, die sie anvisieren; außerhalb des Kampfes hebt ein Druck, der keins von beiden findet, dein Ziel auf. Deine Gruppe sieht die Markierungen; in einem Schlachtzug können nur der Leiter und Assistenten sie setzen."
-- L["The last guides you loaded."] = "Die zuletzt geladenen Guides."
-- L["Three choices to start with. Everything else is in %s."] = "Drei Einstellungen für den Anfang. Alles andere findest du unter %s."
-- L["The way to the goal on the world map and the minimap: dots where you walk, lines where you fly, sail or ride, the legs after this one fainter. Drawn as Shortest Path Forever by Cillian Berragan draws them."] = "Der Weg zum Ziel auf der Weltkarte und der Minikarte: Punkte, wo du läufst, Linien, wo du fliegst, segelst oder fährst, die Etappen nach dieser blasser. Gezeichnet, wie Shortest Path Forever von Cillian Berragan sie zeichnet."
-- L["How the route lines are drawn: Polestar's dots, or sparkles that drift along the way to the goal."] = "Wie die Routenlinien gezeichnet werden: als Punkte von Polestar oder als Funken, die auf dem Weg zum Ziel treiben."
-- L["The first walk of %s"] = "Der erste Weg in %s"
-- L["Browse folders fold away, a closed tab comes back with Reopen, the route line can be a line, dots or sparkles on the map and minimap, and a floating Polestar button can be turned on in Options."] = "Die Ordner der Guide-Liste lassen sich zuklappen, ein geschlossener Tab kommt mit „Wieder öffnen“ zurück, die Routenlinie kann auf Karte und Minikarte eine Linie, Punkte oder Funken sein, und ein schwebender Polestar-Button lässt sich in den Optionen einschalten."
-- L["Found something off?"] = "Etwas stimmt nicht?"
-- L["Type %s right where it happens."] = "Gib %s genau dort ein, wo es passiert."
-- L["Guide menu and minimap"] = "Guide-Menü und Minikarte"
-- L["Quests asked for before the game offers them, wrong spots, dungeon pick-ups, guides opened part-way, the arrow while you're a ghost, and lots more."] = "Quests, die verlangt wurden, bevor das Spiel sie anbietet, falsche Orte, Dungeon-Quests zum Abholen, mittendrin geöffnete Guides, der Pfeil als Geist und vieles mehr."
-- L["Grinding steps point at where the mob is found, and on a step with several camps the arrow moves on from one you've emptied. The Target button shows who it targets, the While you're here mobs included."] = "Grind-Schritte zeigen dorthin, wo der Mob zu finden ist, und bei einem Schritt mit mehreren Lagern zieht der Pfeil von einem geleerten weiter. Der Ziel-Button zeigt, wen er anvisiert, auch die Mobs von „Wenn du schon hier bist“."
-- L["Every leveling guide was gone over again, and 40-60 reworked for both factions with more quests and shorter grinds. Quests new in Forever carry a small ∞ mark. If the guide you had open doesn't match where you are, open the guide list and pick the guide under %s. Your quest log carries over."] = "Jeder Level-Guide wurde noch einmal durchgesehen, und 40-60 wurde für beide Fraktionen überarbeitet, mit mehr Quests und kürzerem Grinden. Quests, die in Forever neu sind, tragen ein kleines ∞-Zeichen. Passt der Guide, den du offen hattest, nicht mehr zu deinem Standort, öffne die Guide-Liste und wähle den Guide unter %s. Dein Questlog bleibt erhalten."
-- L["Browse folders fold away, a closed tab comes back with Reopen, the route line can be a line, dots or sparkles on the map and minimap, and the minimap button and a floating Polestar button can be turned on in Options."] = "Ordner beim Durchsuchen lassen sich einklappen, ein geschlossener Tab kommt mit „Wieder öffnen“ zurück, die Route kann auf Karte und Minikarte als Linie, Punkte oder Funken erscheinen, und der Minikarten-Button und ein schwebender Polestar-Button lassen sich in den Optionen einschalten."
-- L["Leveling guides take you through this dungeon where they have steps for it. Off: they keep to the solo route."] = "Leveling-Guides führen dich durch diesen Dungeon, wo sie Schritte dafür haben. Aus: Sie bleiben auf der Solo-Route."
-- L["With Transparent, a shade with no edge behind the text, so it reads over bright ground. Off: the outlined text alone on the world."] = "Bei Transparent ein Schatten ohne Rand hinter dem Text, damit er auch vor hellem Hintergrund lesbar bleibt. Aus: nur der umrandete Text über der Welt."
-- L["The route's line, dots or sparkles on the minimap, and the gaps between the dots; the world map keeps its own. Right-click to reset."] = "Die Linie, Punkte oder Funken der Route auf der Minikarte und die Abstände zwischen den Punkten; die Weltkarte behält ihre eigenen. Rechtsklick zum Zurücksetzen."
-- L["Behind: %s (%d) at step %d, you'll be %s; grind ~%s first"] = "Rückstand: %s (%d) bei Schritt %d, du bist dann auf Stufe %s; erst ~%s grinden"
-- L["Behind: %s (%d) at step %d, you'll be %s; reach %d first"] = "Rückstand: %s (%d) bei Schritt %d, du bist dann auf Stufe %s; erst Stufe %d erreichen"
-- L["1 bar"] = "1 Balken"
-- L["%d bars"] = "%d Balken"
-- L["On pace, but %s (%d) at step %d is hard: you'll be %s; grind ~%s first"] = "Im Plan, aber %s (%d) bei Schritt %d ist schwer: du bist dann auf Stufe %s; erst ~%s grinden"
-- L["On pace, but %s (%d) at step %d is hard: you'll be %s; reach %d first"] = "Im Plan, aber %s (%d) bei Schritt %d ist schwer: du bist dann auf Stufe %s; erst Stufe %d erreichen"
-- L["%s has Polestar %s; you have %s. A newer version is out."] = "%s hat Polestar %s; du hast %s. Eine neuere Version ist erschienen."
-- L["Party sync is on: your party sees your quest progress (Options > Questing > Quests > Group to turn it off)."] = "Der Gruppenabgleich ist an: Deine Gruppe sieht deinen Questfortschritt (ausschalten unter Optionen > Questen > Quests > Gruppe)."
-- L["Hide the guide window"] = "Guide-Fenster ausblenden"
-- L["Click the minimap button or press %s to show it."] = "Klicke auf den Minikarten-Button oder drücke %s, um das Fenster anzuzeigen."
-- L["Click the minimap button to show it."] = "Klicke auf den Minikarten-Button, um das Fenster anzuzeigen."
-- L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. The minimap button, the key binding or /polestar opens it there until you leave."] = "Was das Fenster, seine Buttons und Warnungen in Dungeons, Schlachtzügen, Schlachtfeldern und Arenen tun. Der Minikarten-Button, die Tastenbelegung oder /polestar öffnet es dort, bis du gehst."
-- L["A small Polestar button you can put anywhere on the screen. Click to show or hide the guide, right-click for a menu, drag to move it. It hides with the window in combat and in dungeons when those are set to Hide."] = "Ein kleiner Polestar-Button, den du überall auf dem Bildschirm platzieren kannst. Klicken zeigt oder verbirgt den Guide, Rechtsklick öffnet ein Menü, Ziehen verschiebt ihn. Er verschwindet mit dem Fenster im Kampf und in Dungeons, wenn diese auf Ausblenden stehen."
-- L["A Polestar button on the edge of the minimap. Click to show or hide the guide, right-click for settings, drag to move it."] = "Ein Polestar-Button am Rand der Minikarte. Klicke, um den Guide ein- oder auszublenden, Rechtsklick für die Einstellungen, ziehen zum Verschieben."
-- L["Click: show or hide the guide"] = "Klick: Guide ein- oder ausblenden"
-- L["Show window"] = "Fenster anzeigen"
-- L["How near its spawn area must be for a suggestion to show. It goes again a little further out."] = "Wie nah sein Spawn-Gebiet sein muss, damit ein Vorschlag erscheint. Etwas weiter draußen verschwindet er wieder."
-- L["Clears your manual check-offs and skipped steps for this guide."] = "Löscht deine manuell abgehakten Ziele und übersprungenen Schritte für diesen Guide."
-- L["Manual check-offs and skips, current guide."] = "Manuelle Haken und übersprungene Schritte, aktueller Guide."
-- L["Your manual check-offs and skipped steps in %s are cleared. Quests you have done stay done."] = "Deine manuellen Häkchen und übersprungenen Schritte in %s werden gelöscht. Erledigte Quests bleiben erledigt."
-- L["Your manual check-offs and skipped steps in the current guide are cleared. Quests you have done stay done."] = "Deine manuellen Häkchen und übersprungenen Schritte im aktuellen Guide werden gelöscht. Erledigte Quests bleiben erledigt."
-- L["How deep the night runs. Dusk is the default, Night the darkest, Graphite a neutral grey; EllesmereUI takes its panel colour and accent."] = "Wie tief die Nacht reicht. Dämmerung ist der Standard, Nacht das dunkelste, Graphit ein neutrales Grau; EllesmereUI übernimmt dessen Fensterfarbe und Akzent."
-- L["Appearance"] = "Aussehen"
-- L["Points to the current goal. Its look and colours are under Appearance, Arrow."] = "Zeigt zum aktuellen Ziel. Aussehen und Farben findest du unter Aussehen, Pfeil."
-- L["Colour & type"] = "Farbe & Schrift"
-- L["Colours, type, window frames and the arrow. Everything repaints as you change it; right-click a setting to reset it."] = "Farben, Schrift, Fensterrahmen und der Pfeil. Alles wird beim Ändern sofort neu gezeichnet; Rechtsklick auf eine Einstellung setzt sie zurück."
-- L["Type & motion"] = "Schrift & Bewegung"
-- L["Frame"] = "Rahmen"
-- L["The whole guide window, text included. The background's own opacity is under Colour & type."] = "Das ganze Guide-Fenster, Text eingeschlossen. Die Deckkraft des Hintergrunds findest du unter Farbe & Schrift."
-- L["Map icons"] = "Kartensymbole"
-- L["Polestar's marks on the minimap; the world map keeps its own. A mark over your arrow fades so the arrow shows through it. Right-click to reset."] = "Polestars Markierungen auf der Minikarte; die Weltkarte behält ihre eigenen. Eine Markierung über deinem Pfeil wird blasser, damit der Pfeil durchscheint. Rechtsklick zum Zurücksetzen."
-- L["Sparkle"] = "Funkeln"
-- L["Route line style"] = "Stil der Routenlinie"
-- L["Route colours tint each leg by how you travel it. Cyan, magenta and white stand apart from the minimap's yellow herb and ore dots and its gold quest marks. Right-click to reset."] = "Routenfarben tönen jede Etappe danach, wie du sie zurücklegst. Cyan, Magenta und Weiß heben sich von den gelben Kräuter- und Erzpunkten der Minikarte und ihren goldenen Quest-Markierungen ab. Rechtsklick zum Zurücksetzen."
-- L["How thick the solid line is on the world map; the minimap's follows its size. Right-click to reset."] = "Wie dick die durchgehende Linie auf der Weltkarte ist; die der Minikarte folgt ihrer Größe. Rechtsklick zum Zurücksetzen."
-- L["Accent colour"] = "Akzentfarbe"
-- L["Background opacity"] = "Hintergrund-Deckkraft"
-- L["Border thickness"] = "Randstärke"
-- L["Window scale"] = "Fenstergröße"
-- L["Window opacity"] = "Fenster-Deckkraft"
-- L["Menus"] = "Menüs"
-- L["Arrow style"] = "Pfeilstil"
-- L["Arrow scale"] = "Pfeilgröße"
-- L["Arrow opacity"] = "Pfeil-Deckkraft"
-- L["Colours"] = "Farben"
-- L["Arrival colour"] = "Ankunftsfarbe"
-- L["The arrow as it closes on the target, and the ring when you arrive. Right-click to go back to jade."] = "Der Pfeil, wenn er sich dem Ziel nähert, und der Ring bei der Ankunft. Rechtsklick, um zu Jade zurückzukehren."
-- L["A short chime the first time a class quest chain's card shows. Off while the game's sound effects are off."] = "Ein kurzer Signalton, wenn die Karte einer Klassenquestreihe zum ersten Mal erscheint. Aus, solange die Soundeffekte des Spiels aus sind."
-- L["Minimap icon size"] = "Symbolgröße auf der Minikarte"
-- L["Button in the game menu"] = "Button im Spielmenü"
-- L["Keep the bar shown"] = "Leiste immer anzeigen"
-- L["Button size"] = "Button-Größe"
-- L["Target name position"] = "Position des Zielnamens"
-- L["Scale of the quest item, Hearthstone, target and rare buttons. Drag one to move them all."] = "Größe der Knöpfe für Questgegenstand, Ruhestein, Ziel und Rare. Zieh einen, um alle zu verschieben."
-- L["How bright each sparkle and its glow are."] = "Wie hell jeder Funke und sein Leuchten ist."
-- L["How close together the sparkles sit, the same at any zoom."] = "Wie dicht die Funken beieinander sitzen, bei jedem Zoom gleich."
-- L["Flow toward goal"] = "Fluss zum Ziel"
-- L["Most sparkles shown"] = "Höchstzahl an Funken"
-- L["Line thickness"] = "Linienstärke"
-- L["How strongly the route shows on the minimap, line, dots or sparkles; the world map keeps its own. Right-click to reset."] = "Wie stark die Route auf der Minikarte erscheint, als Linie, Punkte oder Funken; die Weltkarte behält ihre eigene. Rechtsklick zum Zurücksetzen."
-- L["The route's line, dots or sparkles on the minimap, each style its own size; the world map keeps its own. Right-click to reset."] = "Linie, Punkte oder Funken der Route auf der Minikarte, jeder Stil mit eigener Größe; die Weltkarte behält ihre eigene. Rechtsklick zum Zurücksetzen."
-- L["Learn new spells"] = "Neue Zauber lernen"
-- L["Learns every spell a class trainer offers that you can afford, and prints the total. Profession trainers are left alone. Hold Shift to skip."] = "Lernt jeden Zauber, den ein Klassenlehrer anbietet und den du dir leisten kannst, und gibt die Gesamtkosten aus. Berufslehrer werden ausgelassen. Halte Umschalt gedrückt, um es auszulassen."
-- L["Rares & travel"] = "Rares & Reisen"
-- L["Tooltips and quest log"] = "Tooltips und Questlog"
-- L["Comparison"] = "Vergleich"
-- L["History"] = "Verlauf"
-- L["Instance limits"] = "Instanzlimits"
-- L["Polestar's own look (the default), Halo (no frame, a soft dark veil, Fira Sans), Hearth (warm game colours), or the game's own art: WoW Forever, Blizzard and Classic. Style, compact mode and the colours you pick work in each."] = "Polestars eigenes Aussehen (Standard), Halo (ohne Rahmen, ein weicher dunkler Schleier, Fira Sans), Herd (warme Farben des Spiels) oder die Grafik des Spiels selbst: WoW Forever, Blizzard und Classic. Stil, Kompaktmodus und die Farben, die du wählst, wirken in jedem Design."
-- L["Tirisfal Glades"] = "Tirisfal"
-- L["Garren's Haunt"] = "Garrens Schlupfwinkel"
-- L["Collect Doom Weed"] = "Sammle Verdammniskraut"
-- L["381 yd"] = "381 yd"
-- L["Dungeons and battlegrounds"] = "Dungeons und Schlachtfelder"
-- L["How near its spawn area must be for a suggestion to show. It goes again a little further out."] = "Wie nah sein Spawn-Gebiet sein muss, damit ein Vorschlag erscheint. Etwas weiter draußen verschwindet er wieder."
-- L["The Dungeons section is turned off. Turn it on under Options > Discovery > Dungeons."] = "Der Bereich Dungeons ist ausgeschaltet. Schalte ihn unter Optionen > Entdecken > Dungeons ein."
-- L["Loot and merchants"] = "Beute und Händler"
-- L["When %s comes into sight, a card says so and the rare button targets him and waves. At most once every half hour, never in combat or instances."] = "Wenn %s in Sicht kommt, sagt es eine Karte, und der Rare-Knopf visiert ihn an und winkt. Höchstens einmal pro halbe Stunde, nie im Kampf oder in Instanzen."
-- L["Dungeons are turned off (Options > Discovery > Dungeons)."] = "Dungeons sind ausgeschaltet (Optionen > Entdecken > Dungeons)."
-- L["The XP tracker is off (Options > Quality of Life > Trackers)."] = "Der EP-Tracker ist aus (Optionen > Komfort > Tracker)."
-- L["Characters is turned off. Turn it on under Options > Discovery > Characters."] = "Charaktere ist ausgeschaltet. Schalte es unter Optionen > Entdecken > Charaktere ein."
-- L["Dungeon heads-ups are off. Turn them back on under Options > Discovery > Dungeons."] = "Dungeon-Hinweise sind aus. Schalte sie unter Optionen > Entdecken > Dungeons wieder ein."
-- L["Colour & type"] = "Farbe & Schrift"
-- L["Manual check-offs and skips, current guide."] = "Manuelle Haken und übersprungene Schritte, aktueller Guide."
-- L["Adds a Train All button to the trainer window to learn all available skills."] = "Fügt dem Lehrerfenster einen Button „Alles lernen“ hinzu, der alle verfügbaren Fertigkeiten lernt."
-- L["Auto-learn new spells"] = "Neue Zauber automatisch lernen"
-- L["Automatically learns every spell a class trainer offers that you can afford, and prints the total. Profession trainers are left alone. Hold Shift to skip."] = "Lernt automatisch jeden Zauber, den ein Klassenlehrer anbietet und den du dir leisten kannst, und gibt die Gesamtkosten aus. Berufslehrer werden ausgelassen. Halte Umschalt gedrückt, um es auszulassen."
-- L["Learned %d spell for %s."] = "%d Zauber für %s gelernt."
-- L["Learned %d spells for %s."] = "%d Zauber für %s gelernt."
-- L["Not enough money for %d more (%s)."] = "Nicht genug Geld für %d weitere (%s)."
-- L["Train %d skill for %s"] = "%d Fertigkeit für %s lernen"
-- L["Train %d skills for %s"] = "%d Fertigkeiten für %s lernen"
-- L["Train All"] = "Alles lernen"
-- L["Train all button"] = "Button „Alles lernen“"
-- L["Taking %s closes %s for good."] = "%s anzunehmen schließt %s endgültig."
-- L["A level-up card lists what to train; %s learns it (thanks RikyZ90); %s updates your bars."] = "Beim Stufenaufstieg zeigt eine Karte neue Zauber; %s lernt alle (danke RikyZ90); %s setzt neue Ränge in die Leisten."
-- L["Every Polestar setting goes back to its default. Your guides and progress are kept."] = "Jede Polestar-Einstellung kehrt zu ihrem Standard zurück. Deine Guides und dein Fortschritt bleiben erhalten."
-- L["The target button and the step key ping the mob they target, so your group sees it behind rocks and buildings. Never in a raid unless you lead or assist. The rare buttons always ping."] = "Der Ziel-Button und die Schrittetaste pingen den Mob, den sie anvisieren, damit deine Gruppe ihn hinter Felsen und Gebäuden sieht. Im Schlachtzug nie, außer du bist Leiter oder Assistent. Die Rare-Knöpfe pingen immer."
-- L["Show the welcome again"] = "Begrüßung erneut anzeigen"
-- L["Make it yours"] = "Passe Polestar an"
-- L["Every style keeps you out of the other faction's towns and away from zones far above your level."] = "Jeder Stil hält dich aus Städten der anderen Fraktion und fern von Gebieten weit über deiner Stufe."
-- L["Skip keeps these as they are."] = "Überspringen behält diese Einstellungen."
-- L["How the arrow walks you. Change it any time in Options."] = "Wie dich der Pfeil führt. Jederzeit in den Optionen änderbar."
-- L["A few choices to start with. Everything else is in %s."] = "Ein paar Optionen für den Anfang. Alles andere steht unter %s."
-- L["How the way to your goal shows on the world map and the minimap. The line is the easiest to follow; sparkles show as dots while Reduce motion is on."] = "Wie der Weg zu deinem Ziel auf der Weltkarte und der Minikarte erscheint. Die Linie ist am leichtesten zu verfolgen; Funken erscheinen als Punkte, solange Bewegung reduzieren an ist."
-- L["%s, %s or %s on map and minimap: set on the Welcome page or in Options."] = "%s, %s oder %s auf Karte und Minimap: in der Begrüßung oder den Optionen."
-- L["Leveling guides take you through this dungeon where they have steps for it. Off: they keep to the solo route. More dungeons join this list as they are added to the guides' route."] = "Leveling-Guides führen dich durch diesen Dungeon, wo sie Schritte dafür haben. Aus: Sie bleiben auf der Solo-Route. Weitere Dungeons kommen auf diese Liste, sobald sie in die Route der Guides aufgenommen werden."
-- L["Preview"] = "Vorschau"
-- L["Brill"] = "Brill"
-- L["Every Polestar setting goes back to its default. Your guides and progress are kept."] = "Jede Polestar-Einstellung kehrt zu ihrem Standard zurück. Deine Guides und dein Fortschritt bleiben erhalten."
